insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ddf1742-f2e7-5202-8cdc-beef0bf6c2e8', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '92', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏وَمَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏هُزَيْلِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏قَالُوا يَمْسَحُ عَلَى الْجَوْرَبَيْنِ وَإِنْ لَمْ تَكُنْ نَعْلَيْنِ إِذَا كَانَا ‏ ‏ثَخِينَيْنِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏سَمِعْت ‏ ‏صَالِحَ بْنَ مُحَمَّدٍ التِّرْمِذِيَّ ‏ ‏قَال سَمِعْتُ ‏ ‏أَبَا مُقَاتِلٍ السَّمَرْقَنْدِيَّ ‏ ‏يَقُولُ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَبِي حَنِيفَةَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ فَدَعَا بِمَاءٍ فَتَوَضَّأَ وَعَلَيْهِ جَوْرَبَانِ فَمَسْحَ عَلَيْهِمَا ثُمَّ قَالَ فَعَلْتُ الْيَوْمَ شَيْئًا لَمْ أَكُنْ أَفْعَلُهُ مَسَحْتُ عَلَى الْجَوْرَبَيْنِ وَهُمَا غَيْرُ مُنَعَّلَيْنِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a0c142bf-c5a7-5e72-baed-0cb0b21691a8', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '93', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَسَحَ عَلَى الْخُفَّيْنِ وَالْعِمَامَةِ ‏ ‏قَالَ ‏ ‏بَكْرٌ ‏ ‏وَقَدْ سَمِعْتُهُ مِنَ ‏ ‏ابْنِ الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏وَذَكَرَ ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏فِي هَذَا الْحَدِيثِ فِي مَوْضِعٍ آخَرَ ‏ ‏أَنَّهُ مَسَحَ عَلَى ‏ ‏نَاصِيَتِهِ ‏ ‏وَعِمَامَتِهِ ‏ ‏وَقَدْ رُوِيَ هَذَا الْحَدِيثُ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏ذَكَرَ بَعْضُهُمْ الْمَسْحَ عَلَى ‏ ‏النَّاصِيَةِ ‏ ‏وَالْعِمَامَةِ وَلَمْ يَذْكُرْ بَعْضُهُمْ ‏ ‏النَّاصِيَةَ ‏ ‏و سَمِعْت ‏ ‏أَحْمَدَ بْنَ الْحَسَنِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَحْمَدَ بْنَ حَنْبَلٍ ‏ ‏يَقُولُ ‏ ‏مَا رَأَيْتُ بِعَيْنِي مِثْلَ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْقَطَّانِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أُمَيَّةِ ‏ ‏وَسَلْمَانَ ‏ ‏وَثَوْبَانَ ‏ ‏وَأَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَأَنَسٌ ‏ ‏وَبِهِ يَقُولُ ‏ ‏الْأَوْزَاعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏قَالُوا يَمْسَحُ عَلَى الْعِمَامَةِ ‏ ‏و قَالَ ‏ ‏غَيْرُ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ لَا يَمْسَحُ عَلَى الْعِمَامَةِ إِلَّا بِرَأْسِهِ مَعَ الْعِمَامَةِ وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَمَالِكِ بْنِ أَنَسٍ ‏ ‏وَابْنِ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيِّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و سَمِعْت ‏ ‏الْجَارُودَ بْنَ مُعَاذٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَكِيعَ بْنَ الْجَرَّاحِ ‏ ‏يَقُولُ ‏ ‏إِنْ مَسَحَ عَلَى الْعِمَامَةِ يُجْزِئُهُ لِلْأَثَرِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('56cf92b3-f5be-547b-abb5-6dece7290b73', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '94', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏عَنْ ‏ ‏بِلَالٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ ‏ ‏وَالْخِمَارِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81f47e70-f2e5-576d-8855-77f1fc519c9f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '95', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَقَ هُوَ الْقُرَشِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارِ بْنِ يَاسِرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَ السُّنَّةُ يَا ابْنَ أَخِي قَالَ وَسَأَلْتُهُ عَنْ الْمَسْحِ عَلَى الْعِمَامَةِ فَقَالَ ‏ ‏أَمِسَّ الشَّعَرَ الْمَاءَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d95e8a6-a3ec-5928-9492-d75cf893b05b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '96', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُسْلًا فَاغْتَسَلَ مِنْ الْجَنَابَةِ فَأَكْفَأَ الْإِنَاءَ بِشِمَالِهِ عَلَى يَمِينِهِ فَغَسَلَ كَفَّيْهِ ثُمَّ أَدْخَلَ يَدَهُ فِي الْإِنَاءِ فَأَفَاضَ عَلَى فَرْجِهِ ثُمَّ دَلَكَ بِيَدِهِ الْحَائِطَ ‏ ‏أَوْ الْأَرْضَ ‏ ‏ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ وَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ ثُمَّ أَفَاضَ عَلَى رَأْسِهِ ثَلَاثًا ثُمَّ أَفَاضَ عَلَى سَائِرِ جَسَدِهِ ثُمَّ تَنَحَّى فَغَسَلَ رِجْلَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَجَابِرٍ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَجُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏وَأَبِي هُرَيْرَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('312c7512-20cd-52c4-91ee-cca4728f005d', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '97', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَغْتَسِلَ مِنْ الْجَنَابَةِ بَدَأَ فَغَسَلَ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَهُمَا الْإِنَاءَ ثُمَّ غَسَلَ فَرْجَهُ وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ ‏ ‏يُشَرِّبُ شَعْرَهُ ‏ ‏الْمَاءَ ثُمَّ ‏ ‏يَحْثِي ‏ ‏عَلَى رَأْسِهِ ثَلَاثَ ‏ ‏حَثَيَاتٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ الَّذِي اخْتَارَهُ أَهْلُ الْعِلْمِ فِي الْغُسْلِ مِنْ الْجَنَابَةِ أَنَّهُ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يُفْرِغُ عَلَى رَأْسِهِ ثَلَاثَ مَرَّاتٍ ثُمَّ يُفِيضُ الْمَاءَ عَلَى سَائِرِ جَسَدِهِ ثُمَّ يَغْسِلُ قَدَمَيْهِ وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ ‏ ‏وَقَالُوا إِنْ انْغَمَسَ الْجُنُبُ فِي الْمَاءِ وَلَمْ يَتَوَضَّأْ أَجْزَأَهُ وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af94a850-c94a-53ea-b111-edafed14aa15', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '98', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ أَشُدُّ ضَفْرَ رَأْسِي أَفَأَنْقُضُهُ لِغُسْلِ الْجَنَابَةِ قَالَ ‏ ‏لَا إِنَّمَا يَكْفِيكِ أَنْ ‏ ‏تَحْثِينَ ‏ ‏عَلَى رَأْسِكِ ثَلَاثَ ‏ ‏حَثَيَاتٍ ‏ ‏مِنْ مَاءٍ ثُمَّ تُفِيضِينَ عَلَى سَائِرِ جَسَدِكِ الْمَاءَ فَتَطْهُرِينَ ‏ ‏أَوْ قَالَ فَإِذَا أَنْتِ قَدْ تَطَهَّرْتِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ أَنَّ الْمَرْأَةَ إِذَا اغْتَسَلَتْ مِنْ الْجَنَابَةِ فَلَمْ تَنْقُضْ شَعْرَهَا أَنَّ ذَلِكَ يُجْزِئُهَا بَعْدَ أَنْ تُفِيضَ الْمَاءَ عَلَى رَأْسِهَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6676082-7972-5f7f-911d-f556ae93eea7', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '99', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ وَجِيهٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكُ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَحْتَ كُلِّ شَعْرَةٍ جَنَابَةٌ فَاغْسِلُوا الشَّعْرَ وَأَنْقُوا الْبَشَرَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَأَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏الْحَارِثِ بْنِ وَجِيهٍ ‏ ‏حَدِيثٌ غَرِيبٌ ‏ ‏لَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِهِ وَهُوَ شَيْخٌ لَيْسَ بِذَاكَ ‏ ‏وَقَدْ رَوَى عَنْهُ غَيْرُ وَاحِدٍ مِنْ الْأَئِمَّةِ وَقَدْ تَفَرَّدَ بِهَذَا الْحَدِيثِ عَنْ ‏ ‏مَالِكِ بْنِ دِينَارٍ ‏ ‏وَيُقَالُ ‏ ‏الْحَارِثُ بْنُ وَجِيهٍ ‏ ‏وَيُقَالُ ‏ ‏ابْنُ وَجْبَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a2e852da-466f-5b56-af0e-a19ff549150a', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '100', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَتَوَضَّأُ بَعْدَ الْغُسْلِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَذَا قَوْلُ غَيْرِ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ أَنْ لَا يَتَوَضَّأَ بَعْدَ الْغُسْلِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('99dfe1ae-909f-5bf1-94b8-45de68597d9b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '101', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُوسَى مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِذَا جَاوَزَ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ فَعَلْتُهُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاغْتَسَلْنَا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَرَافِعِ بْنِ خَدِيجٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81265d0f-a106-5f04-aff9-6a0117e28cc6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '102', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاوَزَ الْخِتَانُ الْخِتَانَ وَجَبَ الْغُسْلُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَائِشَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏وَقَدْ رُوِيَ هَذَا الْحَدِيثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غَيْرِ وَجْهٍ إِذَا جَاوَزَ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏وَعَلِيٌّ ‏ ‏وَعَائِشَةُ ‏ ‏وَالْفُقَهَاءِ مِنْ التَّابِعِينَ وَمَنْ بَعْدَهُمْ مِثْلِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏قَالُوا إِذَا الْتَقَى الْخِتَانَانِ وَجَبَ الْغُسْلُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c33106d8-05c7-550f-8d02-4dc1f5b2c106', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '103', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا كَانَ ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏ ‏رُخْصَةً فِي أَوَّلِ الْإِسْلَامِ ثُمَّ نُهِيَ عَنْهَا ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَإِنَّمَا كَانَ ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏ ‏فِي أَوَّلِ الْإِسْلَامِ ثُمَّ نُسِخَ بَعْدَ ذَلِكَ ‏ ‏وَهَكَذَا رَوَى غَيْرُ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏وَرَافِعُ بْنُ خَدِيجٍ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ عَلَى أَنَّهُ إِذَا جَامَعَ الرَّجُلُ امْرَأَتَهُ فِي الْفَرْجِ وَجَبَ عَلَيْهِمَا الْغُسْلُ وَإِنْ لَمْ يُنْزِلَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae626405-0f96-5875-a11a-20e060659b83', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '104', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي الْجَحَّافِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏ ‏فِي ‏ ‏الِاحْتِلَامِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏سَمِعْت ‏ ‏الْجَارُودَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَكِيعًا ‏ ‏يَقُولُ ‏ ‏لَمْ نَجِدْ هَذَا الْحَدِيثَ إِلَّا عِنْدَ ‏ ‏شَرِيكٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَأَبُو الْجَحَّافِ ‏ ‏اسْمُهُ ‏ ‏دَاوُدُ بْنُ أَبِي عَوْفٍ ‏ ‏وَيُرْوَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْجَحَّافِ ‏ ‏وَكَانَ مَرْضِيًّا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏وَعَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏وَالزُّبَيْرِ ‏ ‏وَطَلْحَةَ ‏ ‏وَأَبِي أَيُّوبَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ce7a19e3-40eb-5c3c-8a46-fbc4cb114870', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '105', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ الْخَيَّاطُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ هُوَ الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ يَجِدُ الْبَلَلَ وَلَا يَذْكُرُ احْتِلَامًا قَالَ ‏ ‏يَغْتَسِلُ وَعَنْ الرَّجُلِ يَرَى أَنَّهُ قَدْ احْتَلَمَ وَلَمْ يَجِدْ بَلَلًا قَالَ لَا غُسْلَ عَلَيْهِ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏يَا رَسُولَ اللَّهِ هَلْ عَلَى الْمَرْأَةِ ‏ ‏تَرَى ذَلِكَ غُسْلٌ قَالَ نَعَمْ إِنَّ النِّسَاءَ ‏ ‏شَقَائِقُ ‏ ‏الرِّجَالِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَإِنَّمَا رَوَى هَذَا الْحَدِيثَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏حَدِيثَ ‏ ‏عَائِشَةَ ‏ ‏فِي الرَّجُلِ يَجِدُ الْبَلَلَ وَلَا يَذْكُرُ احْتِلَامًا ‏ ‏وَعَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏ضَعَّفَهُ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏مِنْ قِبَلِ حِفْظِهِ فِي الْحَدِيثِ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ إِذَا اسْتَيْقَظَ الرَّجُلُ فَرَأَى بِلَّةً أَنَّهُ يَغْتَسِلُ وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ مِنْ التَّابِعِينَ إِنَّمَا يَجِبُ عَلَيْهِ الْغُسْلُ إِذَا كَانَتْ الْبِلَّةُ بِلَّةَ نُطْفَةٍ وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَإِسْحَقَ ‏ ‏وَإِذَا رَأَى احْتِلَامًا وَلَمْ يَرَ بِلَّةً فَلَا غُسْلَ عَلَيْهِ عِنْدَ عَامَّةِ أَهْلِ الْعِلْمِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eb17cc9c-c9ce-5b4a-8807-f54c25d2a74d', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '106', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو السَّوَّاقُ الْبَلْخِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏ح ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمَذْيِ ‏ ‏فَقَالَ ‏ ‏مِنْ ‏ ‏الْمَذْيِ ‏ ‏الْوُضُوءُ وَمِنْ الْمَنِيِّ الْغُسْلُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏الْمِقْدَادِ بْنِ الْأَسْوَدِ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غَيْرِ وَجْهٍ ‏ ‏مِنْ ‏ ‏الْمَذْيِ ‏ ‏الْوُضُوءُ وَمِنْ الْمَنِيِّ الْغُسْلُ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bc8e5d5f-d0c4-55a3-a690-083a923e2dcd', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '107', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدٍ هُوَ ابْنُ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَلْقَى مِنْ ‏ ‏الْمَذْيِ ‏ ‏شِدَّةً وَعَنَاءً فَكُنْتُ أُكْثِرُ مِنْهُ الْغُسْلَ فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَأَلْتُهُ عَنْهُ فَقَالَ ‏ ‏إِنَّمَا يُجْزِئُكَ مِنْ ذَلِكَ الْوُضُوءُ فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ بِمَا يُصِيبُ ثَوْبِي مِنْهُ قَالَ يَكْفِيكَ أَنْ تَأْخُذَ كَفًّا مِنْ مَاءٍ ‏ ‏فَتَنْضَحَ ‏ ‏بِهِ ثَوْبَكَ حَيْثُ ‏ ‏تَرَى أَنَّهُ أَصَابَ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَلَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏فِي ‏ ‏الْمَذْيِ ‏ ‏مِثْلَ هَذَا ‏ ‏وَقَدْ اخْتَلَفَ أَهْلُ الْعِلْمِ فِي ‏ ‏الْمَذْيِ ‏ ‏يُصِيبُ الثَّوْبَ فَقَالَ بَعْضُهُمْ لَا يُجْزِئُ إِلَّا الْغَسْلُ وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَإِسْحَقَ ‏ ‏وَقَالَ بَعْضُهُمْ يُجْزِئُهُ ‏ ‏النَّضْحُ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ ‏ ‏أَرْجُو أَنْ يُجْزِئَهُ ‏ ‏النَّضْحُ ‏ ‏بِالْمَاءِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ed62efda-4d7a-5df1-99f2-5b28ed752e6a', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '108', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏ضَافَ ‏ ‏عَائِشَةَ ‏ ‏ضَيْفٌ ‏ ‏فَأَمَرَتْ لَهُ بِمِلْحَفَةٍ صَفْرَاءَ فَنَامَ فِيهَا فَاحْتَلَمَ فَاسْتَحْيَا أَنْ يُرْسِلَ بِهَا وَبِهَا أَثَرُ ‏ ‏الِاحْتِلَامِ فَغَمَسَهَا فِي الْمَاءِ ثُمَّ أَرْسَلَ بِهَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لِمَ أَفْسَدَ عَلَيْنَا ثَوْبَنَا إِنَّمَا كَانَ يَكْفِيهِ أَنْ يَفْرُكَهُ بِأَصَابِعِهِ وَرُبَّمَا فَرَكْتُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَصَابِعِي ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِنْ الْفُقَهَاءِ مِثْلِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏قَالُوا فِي الْمَنِيِّ يُصِيبُ الثَّوْبَ يُجْزِئُهُ الْفَرْكُ وَإِنْ لَمْ يُغْسَلْ ‏ ‏وَهَكَذَا ‏ ‏رُوِيَ عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَ رِوَايَةِ ‏ ‏الْأَعْمَشِ ‏ ‏وَرَوَى ‏ ‏أَبُو مَعْشَرٍ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَحَدِيثُ ‏ ‏الْأَعْمَشِ ‏ ‏أَصَحُّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
