insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('73172c48-2f86-51a1-9edf-50e738717774', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '110', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ وَهُوَ جُنُبٌ وَلَا يَمَسُّ مَاءً ‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفِيانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَذَا قَوْلُ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏وَغَيْرِهِ ‏ ‏وَقَدْ رَوَى ‏ ‏غَيْرُ وَاحِدٍ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَتَوَضَّأُ قَبْلَ أَنْ يَنَامَ ‏ ‏وَهَذَا أَصَحُّ مِنْ حَدِيثِ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏وَقَدْ رَوَى عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏شُعْبَةُ ‏ ‏وَالثَّوْرِيُّ ‏ ‏وَغَيْرُ وَاحِدٍ ‏ ‏وَيَرَوْنَ أَنَّ هَذَا غَلَطٌ مِنْ ‏ ‏أَبِي إِسْحَقَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4c1630f-0fcb-54ca-a774-1907fb8fac20', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '111', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَنَامُ أَحَدُنَا وَهُوَ جُنُبٌ قَالَ ‏ ‏نَعَمْ إِذَا تَوَضَّأَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏وَعَائِشَةَ ‏ ‏وَجَابِرٍ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عُمَرَ ‏ ‏أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏قَالُوا إِذَا أَرَادَ الْجُنُبُ أَنْ يَنَامَ تَوَضَّأَ قَبْلَ أَنْ يَنَامَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c87ff744-a800-579e-a988-51bacd015821', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '112', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَهُ وَهُوَ جُنُبٌ قَالَ ‏ ‏فَانْبَجَسْتُ ‏ ‏أَيْ ‏ ‏فَانْخَنَسْتُ ‏ ‏فَاغْتَسَلْتُ ثُمَّ جِئْتُ فَقَالَ أَيْنَ كُنْتَ أَوْ أَيْنَ ذَهَبْتَ قُلْتُ إِنِّي كُنْتُ جُنُبًا قَالَ ‏ ‏إِنَّ الْمُسْلِمَ لَا يَنْجُسُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَمَعْنَى قَوْلِهِ فَانْخَنَسْتُ ‏ ‏يَعْنِي تَنَحَّيْتُ عَنْهُ ‏ ‏وَقَدْ رَخَّصَ غَيْرُ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ فِي مُصَافَحَةِ الْجُنُبِ وَلَمْ يَرَوْا بِعَرَقِ الْجُنُبِ وَالْحَائِضِ بَأْسًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9de4ccc4-5f19-5896-b06f-223d74dcf666', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '113', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أُمُّ سُلَيْمٍ بِنْتُ مِلْحَانَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ فَهَلْ عَلَى الْمَرْأَةِ ‏ ‏تَعْنِي غُسْلًا ‏ ‏إِذَا هِيَ رَأَتْ فِي الْمَنَامِ مِثْلَ مَا يَرَى الرَّجُلُ قَالَ ‏ ‏نَعَمْ إِذَا هِيَ رَأَتْ الْمَاءَ فَلْتَغْتَسِلْ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قُلْتُ لَهَا فَضَحْتِ النِّسَاءَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ الْفُقَهَاءِ أَنَّ الْمَرْأَةَ إِذَا رَأَتْ فِي الْمَنَامِ مِثْلَ مَا يَرَى الرَّجُلُ فَأَنْزَلَتْ أَنَّ عَلَيْهَا الْغُسْلَ ‏ ‏وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَالشَّافِعِيُّ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏وَخَوْلَةَ ‏ ‏وَعَائِشَةَ ‏ ‏وَأَنَسٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4a0875db-9509-519b-b07d-33167cfe1b20', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '114', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حُرَيْثٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رُبَّمَا اغْتَسَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ ثُمَّ جَاءَ فَاسْتَدْفَأَ بِي فَضَمَمْتُهُ إِلَيَّ وَلَمْ أَغْتَسِلْ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ لَيْسَ بِإِسْنَادِهِ بَأْسٌ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏وَالتَّابِعِينَ أَنَّ الرَّجُلَ إِذَا اغْتَسَلَ فَلَا بَأْسَ بِأَنْ يَسْتَدْفِئَ بِامْرَأَتِهِ وَيَنَامَ مَعَهَا قَبْلَ أَنْ تَغْتَسِلَ الْمَرْأَةُ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('88766fd2-523d-50cd-82a6-fee35dd2e2e8', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '115', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَمَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ بُجْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الصَّعِيدَ ‏ ‏الطَّيِّبَ طَهُورُ الْمُسْلِمِ وَإِنْ لَمْ يَجِدْ الْمَاءَ عَشْرَ سِنِينَ فَإِذَا وَجَدَ الْمَاءَ فَلْيُمِسَّهُ بَشَرَتَهُ فَإِنَّ ذَلِكَ خَيْرٌ ‏ ‏و قَالَ ‏ ‏مَحْمُودٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏إِنَّ ‏ ‏الصَّعِيدَ ‏ ‏الطَّيِّبَ وَضُوءُ الْمُسْلِمِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَعِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَكَذَا رَوَى غَيْرُ وَاحِدٍ عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ بُجْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏وَقَدْ رَوَى ‏ ‏هَذَا الْحَدِيثَ ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏وَلَمْ يُسَمِّهِ ‏ ‏قَالَ ‏ ‏وَهَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ الْفُقَهَاءِ أَنَّ الْجُنُبَ وَالْحَائِضَ إِذَا لَمْ يَجِدَا الْمَاءَ تَيَمَّمَا وَصَلَّيَا ‏ ‏وَيُرْوَى ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّهُ كَانَ لَا يَرَى التَّيَمُّمَ لِلْجُنُبِ وَإِنْ لَمْ يَجِدْ الْمَاءَ ‏ ‏وَيُرْوَى عَنْهُ أَنَّهُ رَجَعَ عَنْ قَوْلِهِ فَقَالَ يَتَيَمَّمُ إِذَا لَمْ يَجِدْ الْمَاءَ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَمَالِكٌ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
