insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b29811ad-da7c-5bfa-b0e1-a3c952190773', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '117', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي الْيَقْظَانِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏تَدَعُ الصَّلَاةَ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏الَّتِي كَانَتْ تَحِيضُ فِيهَا ثُمَّ تَغْتَسِلُ وَتَتَوَضَّأُ عِنْدَ كُلِّ صَلَاةٍ وَتَصُومُ وَتُصَلِّي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُرَيْكٌ ‏ ‏نَحْوَهُ بِمَعْنَاهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا حَدِيثٌ قَدْ ‏ ‏تَفَرَّدَ بِهِ ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي الْيَقْظَانِ ‏ ‏قَالَ ‏ ‏وَسَأَلْتُ ‏ ‏مُحَمَّدًا ‏ ‏عَنْ ‏ ‏هَذَا الْحَدِيثِ فَقُلْتُ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏جَدُّ ‏ ‏عَدِيٍّ ‏ ‏مَا اسْمُهُ فَلَمْ يَعْرِفْ ‏ ‏مُحَمَّدٌ ‏ ‏اسْمَهُ ‏ ‏وَذَكَرْتُ ‏ ‏لِمُحَمَّدٍ ‏ ‏قَوْلَ ‏ ‏يَحْيَى بْنِ مَعِينٍ ‏ ‏أَنَّ اسْمَهُ ‏ ‏دِينَارٌ ‏ ‏فَلَمْ يَعْبَأْ بِهِ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏إِنْ اغْتَسَلَتْ لِكُلِّ صَلَاةٍ هُوَ أَحْوَطُ لَهَا وَإِنْ تَوَضَّأَتْ لِكُلِّ صَلَاةٍ أَجْزَأَهَا وَإِنْ جَمَعَتْ بَيْنَ الصَّلَاتَيْنِ بِغُسْلٍ وَاحِدٍ أَجْزَأَهَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4f1d8089-29db-5484-b594-f542922efc63', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '118', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامَرٍ الْعَقَدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عِمْرَانَ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏حَمْنَةَ بِنْتِ جَحْشٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُسْتَحَاضُ ‏ ‏حَيْضَةً كَثِيرَةً شَدِيدَةً فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْتَفْتِيهِ وَأُخْبِرُهُ فَوَجَدْتُهُ فِي بَيْتِ أُخْتِي ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أُسْتَحَاضُ ‏ ‏حَيْضَةً كَثِيرَةً شَدِيدَةً فَمَا تَأْمُرُنِي فِيهَا قَدْ مَنَعَتْنِي الصِّيَامَ وَالصَّلَاةَ قَالَ ‏ ‏أَنْعَتُ لَكِ ‏ ‏الْكُرْسُفَ ‏ ‏فَإِنَّهُ يُذْهِبُ الدَّمَ قَالَتْ هُوَ أَكْثَرُ مِنْ ذَلِكَ قَالَ ‏ ‏فَتَلَجَّمِي ‏ ‏قَالَتْ هُوَ أَكْثَرُ مِنْ ذَلِكَ قَالَ فَاتَّخِذِي ثَوْبًا قَالَتْ هُوَ أَكْثَرُ مِنْ ذَلِكَ إِنَّمَا ‏ ‏أَثُجُّ ‏ ‏ثَجًّا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَآمُرُكِ بِأَمْرَيْنِ أَيَّهُمَا صَنَعْتِ أَجْزَأَ عَنْكِ فَإِنْ قَوِيتِ عَلَيْهِمَا فَأَنْتِ أَعْلَمُ فَقَالَ إِنَّمَا هِيَ ‏ ‏رَكْضَةٌ ‏ ‏مِنْ الشَّيْطَانِ فَتَحَيَّضِي سِتَّةَ أَيَّامٍ ‏ ‏أَوْ سَبْعَةَ أَيَّامٍ ‏ ‏فِي عِلْمِ اللَّهِ ثُمَّ اغْتَسِلِي فَإِذَا رَأَيْتِ أَنَّكِ قَدْ طَهُرْتِ ‏ ‏وَاسْتَنْقَأْتِ ‏ ‏فَصَلِّي أَرْبَعًا وَعِشْرِينَ لَيْلَةً ‏ ‏أَوْ ثَلَاثًا وَعِشْرِينَ لَيْلَةً ‏ ‏وَأَيَّامَهَا وَصُومِي وَصَلِّي فَإِنَّ ذَلِكِ يُجْزِئُكِ وَكَذَلِكِ فَافْعَلِي كَمَا تَحِيضُ النِّسَاءُ وَكَمَا يَطْهُرْنَ لِمِيقَاتِ حَيْضِهِنَّ وَطُهْرِهِنَّ فَإِنْ قَوِيتِ عَلَى أَنْ تُؤَخِّرِي الظُّهْرَ وَتُعَجِّلِي ‏ ‏الْعَصْرَ ثُمَّ تَغْتَسِلِينَ حِينَ تَطْهُرِينَ وَتُصَلِّينَ الظُّهْرَ وَالْعَصْرَ جَمِيعًا ثُمَّ تُؤَخِّرِينَ الْمَغْرِبَ وَتُعَجِّلِينَ الْعِشَاءَ ثُمَّ تَغْتَسِلِينَ وَتَجْمَعِينَ بَيْنَ الصَّلَاتَيْنِ فَافْعَلِي وَتَغْتَسِلِينَ مَعَ الصُّبْحِ وَتُصَلِّينَ وَكَذَلِكِ فَافْعَلِي وَصُومِي إِنْ قَوِيتِ عَلَى ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ أَعْجَبُ الْأَمْرَيْنِ إِلَيَّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَرَوَاهُ ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو الرَّقِّيُّ ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏وَشَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عِمْرَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏حَمْنَةَ ‏ ‏إِلَّا أَنَّ ‏ ‏ابْنَ جُرَيجٍ ‏ ‏يَقُولُ ‏ ‏عُمَرُ بْنُ طَلْحَةَ ‏ ‏وَالصَّحِيحُ ‏ ‏عِمْرَانُ بْنُ طَلْحَةَ ‏ ‏قَالَ ‏ ‏وَسَأَلْتُ ‏ ‏مُحَمَّدًا ‏ ‏عَنْ هَذَا الْحَدِيثِ فَقَالَ هُوَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهَكَذَا ‏ ‏قَالَ ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏هُوَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏فِي ‏ ‏الْمُسْتَحَاضَةِ ‏ ‏إِذَا كَانَتْ تَعْرِفُ حَيْضَهَا بِإِقْبَالِ الدَّمِ وَإِدْبَارِهِ وَإِقْبَالُهُ أَنْ يَكُونَ أَسْوَدَ وَإِدْبَارُهُ أَنْ يَتَغَيَّرَ إِلَى الصُّفْرَةِ فَالْحُكْمُ لَهَا عَلَى حَدِيثِ ‏ ‏فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ ‏ ‏وَإِنْ كَانَتْ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏لَهَا أَيَّامٌ مَعْرُوفَةٌ قَبْلَ أَنْ ‏ ‏تُسْتَحَاضَ ‏ ‏فَإِنَّهَا تَدَعُ الصَّلَاةَ أَيَّامَ ‏ ‏أَقْرَائِهَا ‏ ‏ثُمَّ تَغْتَسِلُ وَتَتَوَضَّأُ لِكُلِّ صَلَاةٍ ‏ ‏وَتُصَلِّي وَإِذَا اسْتَمَرَّ بِهَا الدَّمُ وَلَمْ يَكُنْ لَهَا أَيَّامٌ مَعْرُوفَةٌ وَلَمْ تَعْرِفْ الْحَيْضَ بِإِقْبَالِ الدَّمِ وَإِدْبَارِهِ فَالْحُكْمُ لَهَا عَلَى حَدِيثِ ‏ ‏حَمْنَةَ بِنْتِ جَحْشٍ ‏ ‏وَكَذَلِكَ قَالَ ‏ ‏أَبُو عُبَيْدٍ ‏ ‏و قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏الْمُسْتَحَاضَةُ ‏ ‏إِذَا اسْتَمَرَّ بِهَا الدَّمُ فِي أَوَّلِ مَا رَأَتْ فَدَامَتْ عَلَى ذَلِكَ فَإِنَّهَا تَدَعُ الصَّلَاةَ مَا بَيْنَهَا وَبَيْنَ خَمْسَةَ عَشَرَ يَوْمًا فَإِذَا طَهُرَتْ فِي خَمْسَةَ عَشَرَ يَوْمًا أَوْ قَبْلَ ذَلِكَ فَإِنَّهَا أَيَّامُ حَيْضٍ فَإِذَا رَأَتْ الدَّمَ أَكْثَرَ مِنْ خَمْسَةَ عَشَرَ يَوْمًا فَإِنَّهَا تَقْضِي صَلَاةَ أَرْبَعَةَ عَشَرَ يَوْمًا ثُمَّ تَدَعُ الصَّلَاةَ بَعْدَ ذَلِكَ أَقَلَّ مَا تَحِيضُ النِّسَاءُ وَهُوَ يَوْمٌ وَلَيْلَةٌ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِي أَقَلِّ الْحَيْضِ وَأَكْثَرِهِ فَقَالَ بَعْضُ أَهْلِ الْعِلْمِ أَقَلُّ الْحَيْضِ ثَلَاثَةٌ وَأَكْثَرُهُ عَشَرَةٌ وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَأَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏وَبِهِ يَأْخُذُ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏وَرُوِيَ عَنْهُ خِلَافُ هَذَا ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ مِنْهُمْ ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏أَقَلُّ الْحَيْضِ يَوْمٌ وَلَيْلَةٌ وَأَكْثَرُهُ خَمْسَةَ عَشَرَ يَوْمًا وَهُوَ قَوْلُ ‏ ‏مَالِكٍ ‏ ‏وَالْأَوْزَاعِيِّ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏وَأَبِي عُبَيْدٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
