insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9182169c-73ee-5599-a056-47e962757ee5', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '120', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَتَقْضِي إِحْدَانَا صَلَاتَهَا أَيَّامَ مَحِيضِهَا فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ كَانَتْ إِحْدَانَا تَحِيضُ فَلَا تُؤْمَرُ بِقَضَاءٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِنْ غَيْرِ وَجْهٍ ‏ ‏أَنَّ الْحَائِضَ لَا تَقْضِي الصَّلَاةَ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ الْفُقَهَاءِ لَا اخْتِلَافَ بَيْنَهُمْ فِي أَنَّ الْحَائِضَ تَقْضِي الصَّوْمَ وَلَا تَقْضِي الصَّلَاةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f7096f60-4920-5940-a033-2c1c3aeda4b0', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '121', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏وَالْحَسَنُ بْنُ عَرَفَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقْرَأْ الْحَائِضُ وَلَا الْجُنُبُ شَيْئًا مِنْ الْقُرْآنِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏ابْنِ عُمَرَ ‏ ‏حَدِيثٌ لَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِ ‏ ‏إِسْمَعِيلَ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقْرَأْ الْجُنُبُ وَلَا الْحَائِضُ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِثْلِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَابْنِ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏قَالُوا لَا تَقْرَأْ الْحَائِضُ وَلَا الْجُنُبُ مِنْ الْقُرْآنِ شَيْئًا إِلَّا طَرَفَ الْآيَةِ وَالْحَرْفَ وَنَحْوَ ذَلِكَ وَرَخَّصُوا لِلْجُنُبِ وَالْحَائِضِ فِي التَّسْبِيحِ وَالتَّهْلِيلِ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏مُحَمَّدَ بْنَ إِسْمَعِيلَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏إِسْمَعِيلَ بْنَ عَيَّاشٍ ‏ ‏يَرْوِي عَنْ أَهْلِ ‏ ‏الْحِجَازِ ‏ ‏وَأَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏أَحَادِيثَ ‏ ‏مَنَاكِيرَ كَأَنَّهُ ضَعَّفَ رِوَايَتَهُ عَنْهُمْ فِيمَا يَنْفَرِدُ بِهِ وَقَالَ إِنَّمَا حَدِيثُ ‏ ‏إِسْمَعِيلَ بْنَ عَيَّاشٍ ‏ ‏عَنْ أَهْلِ ‏ ‏الشَّأْمِ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏إِسْمَعِيلُ بْنُ عَيَّاشٍ ‏ ‏أَصْلَحُ مِنْ ‏ ‏بَقِيَّةَ ‏ ‏وَلِبَقِيَّةَ ‏ ‏أَحَادِيثُ ‏ ‏مَنَاكِيرُ عَنْ الثِّقَاتِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ الْحَسَنِ ‏ ‏قَال سَمِعْتُ ‏ ‏أَحْمَدَ بْنَ حَنْبَلٍ ‏ ‏يَقُولُ ذَلِكَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_numb