insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aa9c5413-0b10-5049-9a9c-be3788547a6e', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '123', '‏ ‏حَدَّثَنَا ‏ ‏عَبَّاسٌ الْعَنْبَرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏مُوَاكَلَةِ الْحَائِضِ فَقَالَ ‏ ‏وَاكِلْهَا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَأَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ أَهْلِ الْعِلْمِ لَمْ يَرَوْا ‏ ‏بِمُوَاكَلَةِ الْحَائِضِ بَأْسًا ‏ ‏وَاخْتَلَفُوا فِي ‏ ‏فَضْلِ وَضُوئِهَا ‏ ‏فَرَخَّصَ فِي ذَلِكَ بَعْضُهُمْ وَكَرِهَ بَعْضُهُمْ فَضْلَ طَهُورِهَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dea4efda-8e74-595a-a5af-7c600899a642', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '124', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏قَالَتْ لِي ‏ ‏عَائِشَةُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ قَالَتْ قُلْتُ إِنِّي حَائِضٌ قَالَ إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَائِشَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ أَهْلِ الْعِلْمِ لَا نَعْلَمُ بَيْنَهُمْ اخْتِلَافًا فِي ذَلِكَ بِأَنْ لَا بَأْسَ أَنْ تَتَنَاوَلَ الْحَائِضُ شَيْئًا مِنْ الْمَسْجِدِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a341269f-0c4b-5aa5-84e5-b4dfcfab75df', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '125', '‏ ‏حَدَّثَنَا ‏ ‏بُنْدَارٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَبَهْزُ بْنُ أَسَدٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏حَمَادُ بْنُ سَلَمَةِ ‏ ‏عَنْ ‏ ‏حَكِيمٍ الْأَثْرَمِ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَتَى ‏ ‏حَائِضًا أَوْ امْرَأَةً فِي دُبُرِهَا أَوْ ‏ ‏كَاهِنًا ‏ ‏فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏لَا نَعْرِفُ هَذَا الْحَدِيثَ إِلَّا مِنْ حَدِيثِ ‏ ‏حَكِيمٍ الْأَثْرَمِ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَإِنَّمَا مَعْنَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ عَلَى التَّغْلِيظِ ‏ ‏وَقَدْ رُوِيَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَتَى ‏ ‏حَائِضًا فَلْيَتَصَدَّقْ بِدِينَارٍ ‏ ‏فَلَوْ كَانَ ‏ ‏إِتْيَانُ ‏ ‏الْحَائِضِ كُفْرًا لَمْ يُؤْمَرْ فِيهِ بِالْكَفَّارَةِ ‏ ‏وَضَعَّفَ ‏ ‏مُحَمَّدٌ ‏ ‏هَذَا الْحَدِيثَ مِنْ قِبَلِ إِسْنَادِهِ ‏ ‏وَأَبُو تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏اسْمُهُ ‏ ‏طَرِيفُ بْنُ مُجَالِدٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5955bf33-ee49-5568-8130-a7dc00b623ed', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '126', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ ‏ ‏يَقَعُ ‏ ‏عَلَى امْرَأَتِهِ وَهِيَ حَائِضٌ قَالَ ‏ ‏يَتَصَدَّقُ بِنِصْفِ دِينَارٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('266083bb-f629-50b8-8f8c-eb7ef90eafec', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '127', '‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ حُرَيْثٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ السُّكَّرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ دَمًا أَحْمَرَ فَدِينَارٌ وَإِذَا كَانَ دَمًا أَصْفَرَ فَنِصْفُ دِينَارٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ الْكَفَّارَةِ فِي ‏ ‏إِتْيَانِ ‏ ‏الْحَائِضِ قَدْ رُوِيَ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مَوْقُوفًا وَمَرْفُوعًا ‏ ‏وَهُوَ قَوْلُ بَعْضِ أَهْلِ الْعِلْمِ وَبِهِ يَقُولُ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏يَسْتَغْفِرُ رَبَّهُ وَلَا كَفَّارَةَ عَلَيْهِ ‏ ‏وَقَدْ رُوِيَ نَحْوُ قَوْلِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ بَعْضِ التَّابِعِينَ مِنْهُمْ ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏وَإِبْرَاهِيمُ النَّخَعِيُّ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ عُلَمَاءِ الْأَمْصَارِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d87877c8-1db6-5148-af6b-b82aee21ee49', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '128', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ بِنْتِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الثَّوْبِ يُصِيبُهُ الدَّمُ مِنْ الْحَيْضَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُتِّيهِ ‏ ‏ثُمَّ ‏ ‏اقْرُصِيهِ ‏ ‏بِالْمَاءِ ثُمَّ رُشِّيهِ وَصَلِّي فِيهِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأُمِّ قَيْسِ بْنتِ مِحْصَنٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَسْمَاءَ ‏ ‏فِي غَسْلِ الدَّمِ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ اخْتَلَفَ أَهْلُ الْعِلْمِ فِي الدَّمِ يَكُونُ عَلَى الثَّوْبِ فَيُصَلِّي فِيهِ قَبْلَ أَنْ يَغْسِلَهُ قَالَ بَعْضُ أَهْلِ الْعِلْمِ مِنْ التَّابِعِينَ إِذَا كَانَ الدَّمُ مِقْدَارَ الدِّرْهَمِ فَلَمْ يَغْسِلْهُ وَصَلَّى فِيهِ أَعَادَ الصَّلَاةَ ‏ ‏و قَالَ ‏ ‏بَعْضُهُمْ إِذَا كَانَ الدَّمُ أَكْثَرَ مِنْ قَدْرِ الدِّرْهَمِ أَعَادَ الصَّلَاةَ وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَابْنِ الْمُبَارَكِ ‏ ‏وَلَمْ يُوجِبْ بَعْضُ أَهْلِ الْعِلْمِ مِنْ التَّابِعِينَ وَغَيْرِهِمْ عَلَيْهِ الْإِعَادَةَ وَإِنْ كَانَ أَكْثَرَ مِنْ قَدْرِ الدِّرْهَمِ وَبِهِ يَقُولُ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏و قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏يَجِبُ عَلَيْهِ الْغَسْلُ وَإِنْ كَانَ أَقَلَّ مِنْ قَدْرِ الدِّرْهَمِ وَشَدَّدَ فِي ذَلِكَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fc0b8e91-a9a6-5e39-b652-dc0a0f584cbe', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '129', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُجَاعُ بْنُ الْوَلِيدِ أَبُو بَدْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏عَنْ ‏ ‏مُسَّةَ الْأَزْدِيَّةِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ النُّفَسَاءُ تَجْلِسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعِينَ يَوْمًا فَكُنَّا ‏ ‏نَطْلِي وُجُوهَنَا ‏ ‏بِالْوَرْسِ ‏ ‏مِنْ ‏ ‏الْكَلَفِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ ‏ ‏لَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِ ‏ ‏أَبِي سَهْلٍ ‏ ‏عَنْ ‏ ‏مُسَّةَ الْأَزْدِيَّةِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَاسْمُ ‏ ‏أَبِي سَهْلٍ ‏ ‏كَثِيرُ بْنُ زِيَادٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏عَلِيُّ بْنُ عَبْدِ الْأَعْلَى ‏ ‏ثِقَةٌ ‏ ‏وَأَبُو سَهْلٍ ‏ ‏ثِقَةٌ ‏ ‏وَلَمْ يَعْرِفْ ‏ ‏مُحَمَّدٌ ‏ ‏هَذَا الْحَدِيثَ إِلَّا مِنْ حَدِيثِ ‏ ‏أَبِي سَهْلٍ ‏ ‏وَقَدْ أَجْمَعَ أَهْلُ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ عَلَى أَنَّ النُّفَسَاءَ تَدَعُ الصَّلَاةَ أَرْبَعِينَ يَوْمًا إِلَّا أَنْ ‏ ‏تَرَى الطُّهْرَ قَبْلَ ذَلِكَ فَإِنَّهَا تَغْتَسِلُ وَتُصَلِّي فَإِذَا رَأَتْ الدَّمَ بَعْدَ الْأَرْبَعِينَ فَإِنَّ أَكْثَرَ أَهْلِ الْعِلْمِ قَالُوا لَا تَدَعُ الصَّلَاةَ بَعْدَ الْأَرْبَعِينَ وَهُوَ قَوْلُ أَكْثَرِ الْفُقَهَاءِ ‏ ‏وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏وَيُرْوَى ‏ ‏عَنْ ‏ ‏الْحَسَنِ الْبَصْرِيِّ ‏ ‏أَنَّهُ قَالَ إِنَّهَا تَدَعُ الصَّلَاةَ خَمْسِينَ يَوْمًا إِذَا لَمْ تَرَ الطُّهْرَ ‏ ‏وَيُرْوَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏وَالشَّعْبِيِّ ‏ ‏سِتِّينَ يَوْمًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5c2823d6-5e4c-5f26-8eaa-6f0b4888846b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '130', '‏ ‏حَدَّثَنَا ‏ ‏بُنْدَارٌ مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَطُوفُ عَلَى نِسَائِهِ ‏ ‏فِي غُسْلٍ وَاحِدٍ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَنَسٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَطُوفُ عَلَى نِسَائِهِ ‏ ‏بِغُسْلٍ وَاحِدٍ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْهُمْ ‏ ‏الْحَسَنُ الْبَصْرِيُّ ‏ ‏أَنْ لَا بَأْسَ أَنْ يَعُودَ قَبْلَ أَنْ يَتَوَضَّأَ ‏ ‏وَقَدْ رَوَى ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏هَذَا ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏فَقَالَ عَنْ ‏ ‏أَبِي عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَبُو عُرْوَةَ ‏ ‏هُوَ ‏ ‏مَعْمَرُ بْنُ رَاشِدٍ ‏ ‏وَأَبُو الْخَطَّابِ ‏ ‏قَتَادَةُ بْنُ دِعَامَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَرَوَاهُ بَعْضُهُمْ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَطَّابِ ‏ ‏وَهُوَ خَطَأٌ وَالصَّحِيحُ عَنْ ‏ ‏أَبِي عُرْوَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('59be3f28-23a1-5a9d-8d03-ccfa7fb9e8af', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '131', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَتَى ‏ ‏أَحَدُكُمْ أَهْلَهُ ثُمَّ أَرَادَ أَنْ يَعُودَ فَلْيَتَوَضَّأْ بَيْنَهُمَا وُضُوءًا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي سَعِيدٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏و قَالَ ‏ ‏بِهِ غَيْرُ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ قَالُوا إِذَا جَامَعَ الرَّجُلُ امْرَأَتَهُ ثُمَّ أَرَادَ أَنْ يَعُودَ فَلْيَتَوَضَّأْ قَبْلَ أَنْ يَعُودَ ‏ ‏وَأَبُو الْمُتَوَكِّلِ ‏ ‏اسْمُهُ ‏ ‏عَلِيُّ بْنُ دَاوُدَ ‏ ‏وَأَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏اسْمُهُ ‏ ‏سَعْدُ بْنُ مَالِكِ بْنِ سِنَانٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('98779545-87ab-5295-b7dd-c598d5f65bb7', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '132', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْأَرْقَمِ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَأَخَذَ بِيَدِ رَجُلٍ فَقَدَّمَهُ وَكَانَ إِمَامَ قَوْمِهِ وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ وَوَجَدَ أَحَدُكُمْ الْخَلَاءَ فَلْيَبْدَأْ بِالْخَلَاءِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَثَوْبَانَ ‏ ‏وَأَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَبْدِ اللَّهِ بْنِ الْأَرْقَمِ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏هَكَذَا ‏ ‏رَوَى ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏وَغَيْرُ وَاحِدٍ مِنْ الْحُفَّاظِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْأَرْقَمِ ‏ ‏وَرَوَى ‏ ‏وُهَيْبٌ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْأَرْقَمِ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَبِهِ يَقُولُ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏قَالَا لَا يَقُومُ إِلَى الصَّلَاةِ وَهُوَ يَجِدُ شَيْئًا مِنْ ‏ ‏الْغَائِطِ ‏ ‏وَالْبَوْلِ وَقَالَا إِنْ دَخَلَ فِي الصَّلَاةِ فَوَجَدَ شَيْئًا مِنْ ذَلِكَ فَلَا يَنْصَرِفْ مَا لَمْ يَشْغَلْهُ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ لَا بَأْسَ أَنْ يُصَلِّيَ وَبِهِ ‏ ‏غَائِطٌ ‏ ‏أَوْ بَوْلٌ مَا لَمْ يَشْغَلْهُ ذَلِكَ عَنْ الصَّلَاةِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d659c3f9-ad09-5f77-a00d-ecd90e266b87', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '133', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَجَاءٍ قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أُمِّ وَلَدٍ لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَتْ قُلْتُ ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏إِنِّي امْرَأَةٌ أُطِيلُ ‏ ‏ذَيْلِي ‏ ‏وَأَمْشِي فِي الْمَكَانِ الْقَذِرِ فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطَهِّرُهُ مَا بَعْدَهُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَتَوَضَّأُ مِنْ ‏ ‏الْمَوْطَإِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ قَالُوا إِذَا ‏ ‏وَطِيءَ ‏ ‏الرَّجُلُ عَلَى الْمَكَانِ الْقَذِرِ أَنَّهُ لَا يَجِبُ عَلَيْهِ غَسْلُ الْقَدَمِ إِلَّا أَنْ يَكُونَ رَطْبًا فَيَغْسِلَ مَا أَصَابَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَرَوَى ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أُمِّ وَلَدٍ لِهُودِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَهُوَ وَهَمٌ وَلَيْسَ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏ابْنٌ يُقَالَ لَهُ ‏ ‏هُودٌ ‏ ‏وَإِنَّمَا هُوَ عَنْ ‏ ‏أُمِّ وَلَدٍ لِإِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَهَذَا الصَّحِيحُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('97436000-ced6-5406-b5ef-d58f6a820e71', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '134', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَفْصٍ عَمْرُو بْنُ عَلِيٍّ الْفَلَّاسُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ بِالتَّيَمُّمِ لِلْوَجْهِ وَالْكَفَّيْنِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَمَّارٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏عَمَّارٍ ‏ ‏مِنْ غَيْرِ وَجْهٍ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏عَلِيٌّ ‏ ‏وَعَمَّارٌ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏وَغَيْرِ وَاحِدٍ مِنْ التَّابِعِينَ مِنْهُمْ ‏ ‏الشَّعْبِيُّ ‏ ‏وَعَطَاءٌ ‏ ‏وَمَكْحُولٌ ‏ ‏قَالُوا التَّيَمُّمُ ضَرْبَةٌ لِلْوَجْهِ وَالْكَفَّيْنِ وَبِهِ يَقُولُ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ مِنْهُمْ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَجَابِرٌ ‏ ‏وَإِبْرَاهِيمُ ‏ ‏وَالْحَسَنُ ‏ ‏قَالُوا التَّيَمُّمُ ضَرْبَةٌ لِلْوَجْهِ وَضَرْبَةٌ لِلْيَدَيْنِ إِلَى الْمِرْفَقَيْنِ ‏ ‏وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَمَالِكٌ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَقَدْ رُوِيَ هَذَا الْحَدِيثُ عَنْ ‏ ‏عَمَّارٍ ‏ ‏فِي التَّيَمُّمِ أَنَّهُ قَالَ لِلْوَجْهِ وَالْكَفَّيْنِ مِنْ غَيْرِ وَجْهٍ ‏ ‏وَقَدْ رُوِيَ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَيَمَّمْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَنَاكِبِ وَالْآبَاطِ ‏ ‏فَضَعَّفَ بَعْضُ أَهْلِ الْعِلْمِ حَدِيثَ ‏ ‏عَمَّارٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي التَّيَمُّمِ لِلْوَجْهِ وَالْكَفَّيْنِ لَمَّا رُوِيَ عَنْهُ حَدِيثُ الْمَنَاكِبِ وَالْآبَاطِ ‏ ‏قَالَ ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ بْنِ مَخْلَدٍ الْحَنْظَلِيُّ ‏ ‏حَدِيثُ ‏ ‏عَمَّارٍ ‏ ‏فِي التَّيَمُّمِ لِلْوَجْهِ وَالْكَفَّيْنِ هُوَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَحَدِيثُ ‏ ‏عَمَّارٍ ‏ ‏تَيَمَّمْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَنَاكِبِ وَالْآبَاطِ لَيْسَ هُوَ بِمُخَالِفٍ لِحَدِيثِ الْوَجْهِ وَالْكَفَّيْنِ لِأَنَّ ‏ ‏عَمَّارًا ‏ ‏لَمْ يَذْكُرْ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُمْ بِذَلِكَ وَإِنَّمَا قَالَ فَعَلْنَا كَذَا وَكَذَا فَلَمَّا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ بِالْوَجْهِ وَالْكَفَّيْنِ فَانْتَهَى إِلَى مَا عَلَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَجْهِ وَالْكَفَّيْنِ وَالدَّلِيلُ عَلَى ذَلِكَ مَا أَفْتَى بِهِ ‏ ‏عَمَّارٌ ‏ ‏بَعْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي التَّيَمُّمِ أَنَّهُ قَالَ الْوَجْهِ وَالْكَفَّيْنِ فَفِي هَذَا دَلَالَةٌ أَنَّهُ انْتَهَى إِلَى مَا عَلَّمَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَّمَهُ إِلَى الْوَجْهِ وَالْكَفَّيْنِ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏أَبَا زُرْعَةَ عُبَيْدَ اللَّهِ بْنَ عَبْدِ الْكَرِيمِ ‏ ‏يَقُولُ ‏ ‏لَمْ أَرَ ‏ ‏بِالْبَصْرَةِ ‏ ‏أَحْفَظَ مِنْ هَؤُلَاءِ الثَّلَاثَةِ ‏ ‏عَلِيِّ بْنِ الْمَدِينِيِّ ‏ ‏وَابْنِ الشَّاذَكُونِيِّ ‏ ‏وَعَمْرِو بْنِ عَلِيٍّ الْفَلَّاسِ ‏ ‏قَالَ ‏ ‏أَبُو زُرْعَةَ ‏ ‏وَرَوَى ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَلِيٍّ ‏ ‏حَدِيثًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9490a90d-0f21-5266-953b-3896fbef5f20', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '135', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ خَالِدٍ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏دَاودَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ التَّيَمُّمِ فَقَالَ ‏ ‏إِنَّ اللَّهَ قَالَ فِي كِتَابِهِ حِينَ ذَكَرَ الْوُضُوءَ ‏ { ‏فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ ‏} ‏وَقَالَ فِي التَّيَمُّمِ ‏ { ‏فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ ‏} ‏وَقَالَ ‏ { ‏وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُمَا ‏} ‏فَكَانَتْ السُّنَّةُ فِي الْقَطْعِ الْكَفَّيْنِ إِنَّمَا هُوَ الْوَجْهُ وَالْكَفَّانِ ‏ ‏يَعْنِي التَّيَمُّمَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ غَذِيٌّ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1a512946-7d0f-572e-986c-be422d89664d', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '136', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ عَبْدُ اللَّهِ بْنِ سَعِيدٍ الْأَشَجُّ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏وَعُقْبَةُ بْنُ خَالِدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏وَابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلِمَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقْرِئُنَا الْقُرْآنَ عَلَى كُلِّ حَالٍ مَا لَمْ يَكُنْ جُنُبًا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَلِيٍّ ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَبِهِ قَالَ غَيْرُ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ قَالُوا يَقْرَأُ الرَّجُلُ الْقُرْآنَ عَلَى غَيْرِ وُضُوءٍ وَلَا يَقْرَأُ فِي الْمُصْحَفِ إِلَّا وَهُوَ طَاهِرٌ ‏ ‏وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a8c0b93a-1323-5b70-b049-3a6457028777', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '137', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏وَسَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ الْمَخْزُومِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ أَعْرَابِيٌّ الْمَسْجِدَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فَصَلَّى فَلَمَّا فَرَغَ قَالَ اللَّهُمَّ ارْحَمْنِي ‏ ‏وَمُحَمَّدًا ‏ ‏وَلَا تَرْحَمْ مَعَنَا أَحَدًا فَالْتَفَتَ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَقَدْ ‏ ‏تَحَجَّرْتَ ‏ ‏وَاسِعًا فَلَمْ يَلْبَثْ أَنْ بَالَ فِي الْمَسْجِدِ فَأَسْرَعَ إِلَيْهِ النَّاسُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْرِيقُوا ‏ ‏عَلَيْهِ ‏ ‏سَجْلًا ‏ ‏مِنْ مَاءٍ ‏ ‏أَوْ دَلْوًا مِنْ مَاءٍ ‏ ‏ثُمَّ قَالَ إِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ وَلَمْ تُبْعَثُوا مُعَسِّرِينَ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَحَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏نَحْوَ هَذَا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَوَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ بَعْضِ أَهْلِ الْعِلْمِ وَهُوَ قَوْلُ ‏ ‏أَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏وَقَدْ رَوَى ‏ ‏يُونُسُ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab39b332-5511-5bd2-9e40-51349da1c5b6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '138', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ عَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حَكِيمٍ وَهُوَ ابْنُ عَبَّادِ بْنِ حُنَيْفٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعُ بْنُ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَمَّنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عِنْدَ ‏ ‏الْبَيْتِ ‏ ‏مَرَّتَيْنِ فَصَلَّى الظُّهْرَ فِي الْأُولَى مِنْهُمَا حِينَ كَانَ الْفَيْءُ مِثْلَ ‏ ‏الشِّرَاكِ ‏ ‏ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ كُلُّ شَيْءٍ مِثْلَ ظِلِّهِ ثُمَّ صَلَّى الْمَغْرِبَ حِينَ وَجَبَتْ الشَّمْسُ وَأَفْطَرَ الصَّائِمُ ثُمَّ صَلَّى الْعِشَاءَ حِينَ غَابَ ‏ ‏الشَّفَقُ ‏ ‏ثُمَّ صَلَّى الْفَجْرَ حِينَ ‏ ‏بَرَقَ ‏ ‏الْفَجْرُ وَحَرُمَ الطَّعَامُ عَلَى الصَّائِمِ وَصَلَّى الْمَرَّةَ الثَّانِيَةَ الظُّهْرَ حِينَ كَانَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ لِوَقْتِ الْعَصْرِ بِالْأَمْسِ ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ ثُمَّ صَلَّى الْمَغْرِبَ لِوَقْتِهِ الْأَوَّلِ ثُمَّ صَلَّى الْعِشَاءَ الْآخِرَةَ حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ ثُمَّ صَلَّى الصُّبْحَ حِينَ ‏ ‏أَسْفَرَتْ ‏ ‏الْأَرْضُ ثُمَّ الْتَفَتَ إِلَيَّ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏هَذَا وَقْتُ الْأَنْبِيَاءِ مِنْ قَبْلِكَ وَالْوَقْتُ فِيمَا بَيْنَ هَذَيْنِ الْوَقْتَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَبُرَيْدَةَ ‏ ‏وَأَبِي مُوسَى ‏ ‏وَأَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَجَابِرٍ ‏ ‏وَعَمْرِو بْنِ حَزْمٍ ‏ ‏وَالْبَرَاءِ ‏ ‏وَأَنَسٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏أَخْبَرَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَمَّنِي ‏ ‏جِبْرِيلُ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِمَعْنَاهُ وَلَمْ يَذْكُرْ فِيهِ لِوَقْتِ الْعَصْرِ بِالْأَمْسِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ ‏ ‏وَحَدِيثُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏و قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏أَصَحُّ شَيْءٍ فِي الْمَوَاقِيتِ حَدِيثُ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَحَدِيثُ ‏ ‏جَابِرٍ ‏ ‏فِي الْمَوَاقِيتِ ‏ ‏قَدْ رَوَاهُ ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏وَعَمْرُو بْنُ دِينَارٍ ‏ ‏وَأَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7053a231-1bf3-5e12-9953-66d9b9b27737', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '139', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلصَّلَاةِ أَوَّلًا وَآخِرًا وَإِنَّ أَوَّلَ وَقْتِ صَلَاةِ الظُّهْرِ حِينَ ‏ ‏تَزُولُ ‏ ‏الشَّمْسُ وَآخِرَ وَقْتِهَا حِينَ يَدْخُلُ وَقْتُ الْعَصْرِ وَإِنَّ أَوَّلَ وَقْتِ صَلَاةِ الْعَصْرِ حِينَ يَدْخُلُ وَقْتُهَا وَإِنَّ آخِرَ وَقْتِهَا حِينَ تَصْفَرُّ الشَّمْسُ وَإِنَّ أَوَّلَ وَقْتِ الْمَغْرِبِ حِينَ تَغْرُبُ الشَّمْسُ وَإِنَّ آخِرَ وَقْتِهَا حِينَ يَغِيبُ ‏ ‏الْأُفُقُ ‏ ‏وَإِنَّ أَوَّلَ وَقْتِ الْعِشَاءِ الْآخِرَةِ حِينَ يَغِيبُ ‏ ‏الْأُفُقُ ‏ ‏وَإِنَّ آخِرَ وَقْتِهَا حِينَ يَنْتَصِفُ اللَّيْلُ وَإِنَّ أَوَّلَ وَقْتِ الْفَجْرِ حِينَ يَطْلُعُ الْفَجْرُ وَإِنَّ آخِرَ وَقْتِهَا حِينَ تَطْلُعُ الشَّمْسُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و سَمِعْت ‏ ‏مُحَمَّدًا ‏ ‏يَقُولُ ‏ ‏حَدِيثُ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏فِي الْمَوَاقِيتِ أَصَحُّ مِنْ حَدِيثِ ‏ ‏مُحَمَّدِ بْنِ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَحَدِيثُ ‏ ‏مُحَمَّدِ بْنِ فُضَيْلٍ ‏ ‏خَطَأٌ أَخْطَأَ فِيهِ ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏كَانَ يُقَالُ إِنَّ لِلصَّلَاةِ أَوَّلًا وَآخِرًا فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏مُحَمَّدِ بْنِ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏نَحْوَهُ بِمَعْنَاهُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('44257b39-b546-599c-a4b7-965f9b1102b1', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '140', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏وَالْحَسَنُ بْنُ الصَّبَّاحِ الْبَزَّارُ ‏ ‏وَأَحْمَدُ بْنُ مُحَمَّدِ بْنِ مُوسَى ‏ ‏الْمَعْنَى وَاحِدٌ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏عَنْ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَسَأَلَهُ عَنْ مَوَاقِيتِ الصَّلَاةِ فَقَالَ ‏ ‏أَقِمْ مَعَنَا إِنْ شَاءَ اللَّهُ فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَقَامَ حِينَ طَلَعَ الْفَجْرُ ثُمَّ أَمَرَهُ فَأَقَامَ حِينَ ‏ ‏زَالَتْ ‏ ‏الشَّمْسُ فَصَلَّى الظُّهْرَ ثُمَّ أَمَرَهُ فَأَقَامَ فَصَلَّى الْعَصْرَ وَالشَّمْسُ ‏ ‏بَيْضَاءُ ‏ ‏مُرْتَفِعَةٌ ثُمَّ أَمَرَهُ بِالْمَغْرِبِ حِينَ ‏ ‏وَقَعَ حَاجِبُ الشَّمْسِ ‏ ‏ثُمَّ أَمَرَهُ بِالْعِشَاءِ فَأَقَامَ حِينَ غَابَ ‏ ‏الشَّفَقُ ‏ ‏ثُمَّ أَمَرَهُ مِنْ الْغَدِ ‏ ‏فَنَوَّرَ بِالْفَجْرِ ‏ ‏ثُمَّ أَمَرَهُ بِالظُّهْرِ ‏ ‏فَأَبْرَدَ ‏ ‏وَأَنْعَمَ أَنْ ‏ ‏يُبْرِدَ ‏ ‏ثُمَّ أَمَرَهُ بِالْعَصْرِ فَأَقَامَ وَالشَّمْسُ آخِرَ وَقْتِهَا فَوْقَ مَا كَانَتْ ثُمَّ أَمَرَهُ فَأَخَّرَ الْمَغْرِبَ إِلَى قُبَيْلِ أَنْ يَغِيبَ ‏ ‏الشَّفَقُ ‏ ‏ثُمَّ أَمَرَهُ بِالْعِشَاءِ فَأَقَامَ حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ مَوَاقِيتِ الصَّلَاةِ فَقَالَ الرَّجُلُ أَنَا فَقَالَ مَوَاقِيتُ الصَّلَاةِ كَمَا بَيْنَ هَذَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏وَقَدْ رَوَاهُ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏أَيْضًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('39fa9223-310b-5969-9617-c2d287747bf4', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '141', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصَلِّي الصُّبْحَ فَيَنْصَرِفُ النِّسَاءُ قَالَ ‏ ‏الْأَنْصَارِيُّ ‏ ‏فَيَمُرُّ النِّسَاءُ مُتَلَفِّفَاتٍ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏مَا يُعْرَفْنَ مِنْ ‏ ‏الْغَلَسِ ‏ ‏و قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏مُتَلَفِّعَاتٍ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَأَنَسٍ ‏ ‏وَقَيْلَةَ بِنْتِ مَخْرَمَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَائِشَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رَوَاهُ ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏نَحْوَهُ ‏ ‏وَهُوَ الَّذِي اخْتَارَهُ غَيْرُ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَمَنْ بَعْدَهُمْ مِنْ التَّابِعِينَ وَبِهِ يَقُولُ ‏ ‏الشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏يَسْتَحِبُّونَ ‏ ‏التَّغْلِيسَ ‏ ‏بِصَلَاةِ الْفَجْرِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4eb96dfd-3b3b-51e0-bd06-5505efbe4a1b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '142', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ هُوَ ابْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَسْفِرُوا ‏ ‏بِالْفَجْرِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ ‏ ‏قَالَ ‏ ‏وَقَدْ رَوَى ‏ ‏شُعْبَةُ ‏ ‏وَالثَّوْرِيُّ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏قَالَ ‏ ‏وَرَوَاهُ ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏أَيْضًا ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏وَجَابِرٍ ‏ ‏وَبِلَالٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رَأَى غَيْرُ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ الْإِسْفَارَ بِصَلَاةِ الْفَجْرِ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏و قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏مَعْنَى الْإِسْفَارِ أَنْ يَضِحَ الْفَجْرُ فَلَا يُشَكَّ فِيهِ وَلَمْ يَرَوْا أَنَّ مَعْنَى الْإِسْفَارِ تَأْخِيرُ الصَّلَاةِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d5e24141-d527-5695-b7b6-fecd4835c13c', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '143', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ أَحَدًا كَانَ أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا مِنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَلَا مِنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَخَبَّابٍ ‏ ‏وَأَبِي بَرْزَةَ ‏ ‏وَابْنِ مَسْعُودٍ ‏ ‏وَزَيْدِ بْنِ ثَابِتٍ ‏ ‏وَأَنَسٍ ‏ ‏وَجَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَائِشَةَ ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَهُوَ الَّذِي اخْتَارَهُ أَهْلُ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ الْمَدِينِيِّ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَقَدْ تَكَلَّمَ ‏ ‏شُعْبَةُ ‏ ‏فِي ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏مِنْ أَجْلِ حَدِيثِهِ الَّذِي رَوَى عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ النَّاسَ وَلَهُ مَا يُغْنِيهِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَرَوَى لَهُ ‏ ‏سُفْيَانُ ‏ ‏وَزَائِدَةُ ‏ ‏وَلَمْ يَرَ ‏ ‏يَحْيَى ‏ ‏بِحَدِيثِهِ بَأْسًا ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي تَعْجِيلِ الظُّهْرِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9696c632-65ae-57d2-b3d2-0bba031e9445', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '144', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ حِينَ ‏ ‏زَالَتْ الشَّمْسُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ صَحِيحٌ ‏ ‏وَهُوَ أَحْسَنُ حَدِيثٍ فِي هَذَا الْبَابِ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d289266a-9b5f-5b55-a3f0-39adb6626df9', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '145', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَأَبِي ذَرٍّ ‏ ‏وَابْنِ عُمَرَ ‏ ‏وَالْمُغِيرَةِ ‏ ‏وَالْقَاسِمِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَأَبِي مُوسَى ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَأَنَسٍ ‏ ‏قَالَ ‏ ‏وَرُوِيَ عَنْ ‏ ‏عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا وَلَا يَصِحُّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ اخْتَارَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ تَأْخِيرَ صَلَاةِ الظُّهْرِ فِي شِدَّةِ الْحَرِّ وَهُوَ قَوْلُ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏إِنَّمَا ‏ ‏الْإِبْرَادُ ‏ ‏بِصَلَاةِ الظُّهْرِ إِذَا كَانَ مَسْجِدًا ‏ ‏يَنْتَابُ ‏ ‏أَهْلُهُ مِنْ الْبُعْدِ فَأَمَّا الْمُصَلِّي وَحْدَهُ وَالَّذِي ‏ ‏يُصَلِّي فِي مَسْجِدِ قَوْمِهِ فَالَّذِي أُحِبُّ لَهُ أَنْ لَا يُؤَخِّرَ الصَّلَاةَ فِي شِدَّةِ الْحَرِّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَمَعْنَى مَنْ ذَهَبَ إِلَى تَأْخِيرِ الظُّهْرِ فِي شِدَّةِ الْحَرِّ هُوَ أَوْلَى وَأَشْبَهُ ‏ ‏بِالِاتِّبَاعِ ‏ ‏وَأَمَّا مَا ذَهَبَ إِلَيْهِ ‏ ‏الشَّافِعِيُّ ‏ ‏أَنَّ الرُّخْصَةَ لِمَنْ ‏ ‏يَنْتَابُ ‏ ‏مِنْ الْبُعْدِ وَالْمَشَقَّةِ عَلَى النَّاسِ فَإِنَّ فِي حَدِيثِ ‏ ‏أَبِي ذَرٍّ ‏ ‏مَا يَدُلُّ عَلَى خِلَافِ مَا قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏قَالَ ‏ ‏أَبُو ذَرٍّ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَأَذَّنَ ‏ ‏بِلَالٌ ‏ ‏بِصَلَاةِ الظُّهْرِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بِلَالُ ‏ ‏أَبْرِدْ ‏ ‏ثُمَّ ‏ ‏أَبْرِدْ ‏ ‏فَلَوْ كَانَ الْأَمْرُ عَلَى مَا ذَهَبَ إِلَيْهِ ‏ ‏الشَّافِعِيُّ ‏ ‏لَمْ يَكُنْ ‏ ‏لِلْإِبْرَادِ ‏ ‏فِي ذَلِكَ الْوَقْتِ مَعْنًى لِاجْتِمَاعِهِمْ فِي السَّفَرِ وَكَانُوا لَا يَحْتَاجُونَ أَنْ ‏ ‏يَنْتَابُوا ‏ ‏مِنْ الْبُعْدِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae35377b-df2f-542b-849e-31a5dbd83a2f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '146', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُهَاجِرٍ أَبِي الْحَسَنِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ وَمَعَهُ ‏ ‏بِلَالٌ ‏ ‏فَأَرَادَ أَنْ يُقِيمَ فَقَالَ ‏ ‏أَبْرِدْ ‏ ‏ثُمَّ أَرَادَ أَنْ يُقِيمَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدْ ‏ ‏فِي الظُّهْرِ قَالَ حَتَّى رَأَيْنَا ‏ ‏فَيْءَ ‏ ‏التُّلُولِ ثُمَّ أَقَامَ فَصَلَّى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a66c22d4-6554-5d6a-9241-2e2d5a2da3c6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '147', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا وَلَمْ ‏ ‏يَظْهَرْ ‏ ‏الْفَيْءُ ‏ ‏مِنْ حُجْرَتِهَا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَبِي أَرْوَى ‏ ‏وَجَابِرٍ ‏ ‏وَرَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏وَيُرْوَى عَنْ ‏ ‏رَافِعٍ ‏ ‏أَيْضًا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي تَأْخِيرِ الْعَصْرِ وَلَا يَصِحُّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَائِشَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ الَّذِي اخْتَارَهُ بَعْضُ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏عُمَرُ ‏ ‏وَعَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏وَعَائِشَةُ ‏ ‏وَأَنَسٌ ‏ ‏وَغَيْرُ وَاحِدٍ مِنْ التَّابِعِينَ تَعْجِيلَ صَلَاةِ الْعَصْرِ وَكَرِهُوا تَأْخِيرَهَا وَبِهِ يَقُولُ ‏ ‏عَبْدُ اللَّهِ ابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cdfc83f3-f800-5a28-a0c8-73d6491f4741', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '148', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فِي دَارِهِ ‏ ‏بِالْبَصْرَةِ ‏ ‏حِينَ انْصَرَفَ مِنْ الظُّهْرِ وَدَارُهُ بِجَنْبِ الْمَسْجِدِ فَقَالَ قُومُوا فَصَلُّوا الْعَصْرَ قَالَ فَقُمْنَا فَصَلَّيْنَا فَلَمَّا انْصَرَفْنَا قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تِلْكَ صَلَاةُ الْمُنَافِقِ يَجْلِسُ يَرْقُبُ الشَّمْسَ حَتَّى إِذَا كَانَتْ بَيْنَ ‏ ‏قَرْنَيْ الشَّيْطَانِ ‏ ‏قَامَ فَنَقَرَ أَرْبَعًا لَا يَذْكُرُ اللَّهَ فِيهَا إِلَّا قَلِيلًا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1ec4fb55-c6e5-5a55-8e69-2217789cc847', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '149', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْكُمْ وَأَنْتُمْ أَشَدُّ تَعْجِيلًا لِلْعَصْرِ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رُوِيَ ‏ ‏هَذَا الْحَدِيثُ عَنْ ‏ ‏إِسْمَعِيلَ ابْنِ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏نَحْوَهُ ‏ ‏وَوَجَدْتُ فِي كِتَابِي ‏ ‏أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏و حَدَّثَنَا ‏ ‏بِشْرُ بْنُ مُعَاذٍ الْبَصْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ ‏ ‏وَهَذَا أَصَحُّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6d8955c9-48ba-53bb-abe0-a4f444395743', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '150', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَغْرِبَ إِذَا غَرَبَتْ الشَّمْسُ وَتَوَارَتْ بِالْحِجَابِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَالصُّنَابِحِيِّ ‏ ‏وَزَيْدِ بْنِ خَالِدٍ ‏ ‏وَأَنَسٍ ‏ ‏وَرَافِعِ بْنِ خَدِيجٍ ‏ ‏وَأَبِي أَيُّوبَ ‏ ‏وَأُمِّ حَبِيبَةَ ‏ ‏وَعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَحَدِيثُ ‏ ‏الْعَبَّاسِ ‏ ‏قَدْ رُوِيَ مَوْقُوفًا عَنْهُ وَهُوَ أَصَحُّ ‏ ‏وَالصُّنَابِحِيُّ ‏ ‏لَمْ يَسْمَعْ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ صَاحِبُ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ مِنْ التَّابِعِينَ اخْتَارُوا تَعْجِيلَ صَلَاةِ الْمَغْرِبِ وَكَرِهُوا تَأْخِيرَهَا ‏ ‏حَتَّى قَالَ بَعْضُ أَهْلِ الْعِلْمِ لَيْسَ لِصَلَاةِ الْمَغْرِبِ إِلَّا وَقْتٌ وَاحِدٌ وَذَهَبُوا إِلَى حَدِيثِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيْثُ صَلَّى بِهِ ‏ ‏جِبْرِيلُ ‏ ‏وَهُوَ قَوْلُ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيِّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bd4957f8-c70a-5e88-bc84-64f4b51b1097', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '151', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الشَّوَارِبِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏أَنَا أَعْلَمُ النَّاسِ بِوَقْتِ هَذِهِ الصَّلَاةِ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهَا ‏ ‏لِسُقُوطِ الْقَمَرِ ‏ ‏لِثَالِثَةٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ مُحَمَّدُ بْنُ أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏رَوَى ‏ ‏هَذَا الْحَدِيثَ ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏وَلَمْ يَذْكُرْ فِيهِ ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ ثَابِتٍ ‏ ‏وَحَدِيثُ ‏ ‏أَبِي عَوَانَةَ ‏ ‏أَصَحُّ عِنْدَنَا ‏ ‏لِأَنَّ ‏ ‏يَزِيدَ بْنَ هَارُونَ ‏ ‏رَوَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏نَحْوَ رِوَايَةِ ‏ ‏أَبِي عَوَانَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d9320ce3-c054-55cb-bc91-76251998ce99', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '152', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ أَنْ يُؤَخِّرُوا الْعِشَاءَ إِلَى ثُلُثِ اللَّيْلِ أَوْ نِصْفِهِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏وَجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي بَرْزَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَزَيْدِ بْنِ خَالِدٍ ‏ ‏وَابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ الَّذِي اخْتَارَهُ أَكْثَرُ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَغَيْرِهِمْ رَأَوْا تَأْخِيرَ صَلَاةِ الْعِشَاءِ الْآخِرَةِ وَبِهِ يَقُولُ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c80ba4a0-d438-5481-bcb7-2d1d13d619aa', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '153', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ ‏ ‏أَحْمَدُ ‏ ‏وَحَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ هُوَ الْمُهَلَّبِيُّ ‏ ‏وَإِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏سَيَّارِ بْنِ سَلَامَةَ هُوَ أَبُو الْمِنْهَالِ الرِّيَاحِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ النَّوْمَ قَبْلَ الْعِشَاءِ وَالْحَدِيثَ بَعْدَهَا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَأَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي بَرْزَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ كَرِهَ أَكْثَرُ أَهْلِ الْعِلْمِ النَّوْمَ قَبْلَ صَلَاةِ الْعِشَاءِ وَالْحَدِيثَ بَعْدَهَا وَرَخَّصَ فِي ذَلِكَ بَعْضُهُمْ ‏ ‏و قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَكْثَرُ الْأَحَادِيثِ عَلَى الْكَرَاهِيَةِ وَرَخَّصَ بَعْضُهُمْ فِي النَّوْمِ قَبْلَ صَلَاةِ الْعِشَاءِ فِي رَمَضَانَ ‏ ‏وَسَيَّارُ بْنُ سَلَامَةَ ‏ ‏هُوَ ‏ ‏أَبُو الْمِنْهَالِ الرِّيَاحِيُّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a5c3e657-8fb5-5776-afba-2b1453a8ca9f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '154', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْمُرُ ‏ ‏مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فِي الْأَمْرِ مِنْ أَمْرِ الْمُسْلِمِينَ وَأَنَا مَعَهُمَا ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَأَوْسِ بْنِ حُذَيْفَةَ ‏ ‏وَعِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عُمَرَ ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَقَدْ رَوَى هَذَا الْحَدِيثَ ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏جُعْفِيٍّ ‏ ‏يُقَالُ لَهُ ‏ ‏قَيْسٌ ‏ ‏أَوْ ‏ ‏ابْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏فِي قِصَّةٍ طَوِيلَةٍ ‏ ‏وَقَدْ اخْتَلَفَ أَهْلُ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ فِي ‏ ‏السَّمَرِ ‏ ‏بَعْدَ صَلَاةِ الْعِشَاءِ الْآخِرَةِ فَكَرِهَ قَوْمٌ مِنْهُمْ ‏ ‏السَّمَرَ ‏ ‏بَعْدَ صَلَاةِ الْعِشَاءِ وَرَخَّصَ بَعْضُهُمْ إِذَا كَانَ فِي مَعْنَى الْعِلْمِ وَمَا لَا بُدَّ مِنْهُ مِنْ الْحَوَائِجِ وَأَكْثَرُ الْحَدِيثِ عَلَى الرُّخْصَةِ ‏ ‏قَدْ رُوِيَ عَنْ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏سَمَرَ ‏ ‏إِلَّا لِمُصَلٍّ أَوْ مُسَافِرٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('60020588-6a36-5f1a-9c30-51904c5240c1', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '155', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَمَّارٍ الْحُسَيْنُ بْنُ حُرَيْثٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ الْعُمَرِيِّ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ غَنَّامٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏أُمِّ فَرْوَةَ ‏ ‏وَكَانَتْ مِمَّنْ بَايَعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ ‏ ‏الصَّلَاةُ لِأَوَّلِ وَقْتِهَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('600bcb3b-1258-5abc-a8aa-97fca2fb9070', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '156', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ اللَّهِ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُمَرَ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ يَا ‏ ‏عَلِيُّ ‏ ‏ثَلَاثٌ لَا تُؤَخِّرْهَا الصَّلَاةُ إِذَا ‏ ‏آنَتْ ‏ ‏وَالْجَنَازَةُ إِذَا حَضَرَتْ ‏ ‏وَالْأَيِّمُ ‏ ‏إِذَا وَجَدْتَ لَهَا ‏ ‏كُفْئًا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ حَسَنٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('90f8ce77-e987-583d-ad0e-caa984feb8ab', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '157', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ الْوَلِيدِ الْمَدَنِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَقْتُ الْأَوَّلُ مِنْ الصَّلَاةِ رِضْوَانُ اللَّهِ وَالْوَقْتُ الْآخِرُ عَفْوُ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ ‏ ‏وَقَدْ رَوَى ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَابْنِ عُمَرَ ‏ ‏وَعَائِشَةَ ‏ ‏وَابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أُمِّ فَرْوَةَ ‏ ‏لَا يُرْوَى إِلَّا مِنْ حَدِيثِ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ الْعُمَرِيِّ ‏ ‏وَلَيْسَ هُوَ بِالْقَوِيِّ عِنْدَ أَهْلِ الْحَدِيثِ وَاضْطَرَبُوا عَنْهُ فِي هَذَا الْحَدِيثِ وَهُوَ صَدُوقٌ وَقَدْ تَكَلَّمَ فِيهِ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏مِنْ قِبَلِ حِفْظِهِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f054488b-4074-50e7-a910-84bee149a89b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '158', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِي يَعْفُورٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ الْعَيْزَارِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏أَنَّ رَجُلًا قَالَ ‏ ‏لِابْنِ مَسْعُودٍ ‏ ‏أَيُّ الْعَمَلِ أَفْضَلُ قَالَ سَأَلْتُ عَنْهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏الصَّلَاةُ عَلَى مَوَاقِيتِهَا قُلْتُ وَمَاذَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏وَبِرُّ ‏ ‏الْوَالِدَيْنِ قُلْتُ وَمَاذَا يَا رَسُولَ اللَّهِ قَالَ وَالْجِهَادُ فِي سَبِيلِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رَوَى ‏ ‏الْمَسْعُودِيُّ ‏ ‏وَشُعْبَةُ ‏ ‏وَسُلَيْمَانُ هُوَ أَبُو إِسْحَقَ الشَّيْبَانِيُّ ‏ ‏وَغَيْرُ وَاحِدٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ الْعَيْزَارِ ‏ ‏هَذَا الْحَدِيثَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4c0233df-12d0-5b48-be68-8771e29bdeb6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '159', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً لِوَقْتِهَا الْآخِرِ مَرَّتَيْنِ حَتَّى قَبَضَهُ اللَّهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ وَلَيْسَ إِسْنَادُهُ بِمُتَّصِلٍ ‏ ‏قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏وَالْوَقْتُ الْأَوَّلُ مِنْ الصَّلَاةِ أَفْضَلُ وَمِمَّا يَدُلُّ عَلَى فَضْلِ أَوَّلِ الْوَقْتِ عَلَى آخِرِهِ اخْتِيَارُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏فَلَمْ يَكُونُوا يَخْتَارُونَ إِلَّا مَا هُوَ أَفْضَلُ وَلَمْ يَكُونُوا يَدَعُونَ الْفَضْلَ وَكَانُوا يُصَلُّونَ فِي أَوَّلِ الْوَقْتِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏أَبُو الْوَلِيدِ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏الشَّافِعِيِّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cddc8b51-2b2c-56d2-930e-33201aff2091', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '160', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏بُرَيْدَةَ ‏ ‏وَنَوْفَلِ بْنِ مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏ابْنِ عُمَرَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رَوَاهُ ‏ ‏الزُّهْرِيُّ ‏ ‏أَيْضًا ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0dd64d37-7a19-5dd8-aae1-8be88c144bf0', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '161', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُوسَى الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ الضُّبَعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏أُمَرَاءُ يَكُونُونَ بَعْدِي ‏ ‏يُمِيتُونَ الصَّلَاةَ ‏ ‏فَصَلِّ الصَّلَاةَ لِوَقْتِهَا فَإِنْ صُلِّيَتْ لِوَقْتِهَا كَانَتْ لَكَ نَافِلَةً وَإِلَّا كُنْتَ قَدْ ‏ ‏أَحْرَزْتَ صَلَاتَكَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَعُبَادَةَ بْنِ الصَّامِتِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي ذَرٍّ ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ يَسْتَحِبُّونَ أَنْ يُصَلِّيَ الرَّجُلُ الصَّلَاةَ لِمِيقَاتِهَا إِذَا أَخَّرَهَا الْإِمَامُ ثُمَّ ‏ ‏يُصَلِّي مَعَ الْإِمَامِ وَالصَّلَاةُ الْأُولَى هِيَ الْمَكْتُوبَةُ عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ ‏ ‏وَأَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏اسْمُهُ ‏ ‏عَبْدُ الْمَلِكِ بْنُ حَبِيبٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6662caac-ec9d-5c94-aad4-dd9734d4971a', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '162', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏ذَكَرُوا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَوْمَهُمْ عَنْ الصَّلَاةِ فَقَالَ ‏ ‏إِنَّهُ لَيْسَ فِي النَّوْمِ تَفْرِيطٌ إِنَّمَا التَّفْرِيطُ فِي الْيَقَظَةِ فَإِذَا نَسِيَ أَحَدُكُمْ صَلَاةً أَوْ نَامَ عَنْهَا فَلْيُصَلِّهَا إِذَا ذَكَرَهَا ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏وَأَبِي مَرْيَمَ ‏ ‏وَعِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏وَجُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏وَأَبِي جُحَيْفَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَعَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏وَذِي مِخْبَرٍ ‏ ‏وَيُقَالُ ‏ ‏ذِي مِخْمَرٍ ‏ ‏وَهُوَ ابْنُ أَخِي ‏ ‏النَّجَاشِيِّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏أَبِي قَتَادَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ اخْتَلَفَ أَهْلُ الْعِلْمِ فِي الرَّجُلِ يَنَامُ عَنْ الصَّلَاةِ أَوْ ‏ ‏يَنْسَاهَا فَيَسْتَيْقِظُ أَوْ يَذْكُرُ وَهُوَ فِي غَيْرِ وَقْتِ صَلَاةٍ عِنْدَ طُلُوعِ الشَّمْسِ أَوْ عِنْدَ غُرُوبِهَا ‏ ‏فَقَالَ بَعْضُهُمْ ‏ ‏يُصَلِّيهَا إِذَا اسْتَيْقَظَ أَوْ ذَكَرَ وَإِنْ كَانَ عِنْدَ طُلُوعِ الشَّمْسِ أَوْ عِنْدَ غُرُوبِهَا وَهُوَ قَوْلُ ‏ ‏أَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَمَالِكٍ ‏ ‏و قَالَ ‏ ‏بَعْضُهُمْ لَا ‏ ‏يُصَلِّي حَتَّى تَطْلُعَ الشَّمْسُ أَوْ تَغْرُبَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bf69735e-2d3c-5494-bdf3-8bd6d178d316', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '163', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَبِشْرُ بْنُ مُعَاذٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّهَا إِذَا ذَكَرَهَا ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏وَأَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَنَسٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَيُرْوَى عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي الرَّجُلِ ‏ ‏يَنْسَى الصَّلَاةَ قَالَ ‏ ‏يُصَلِّيهَا مَتَى مَا ذَكَرَهَا فِي وَقْتٍ أَوْ فِي غَيْرِ وَقْتٍ ‏ ‏وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَأَحْمَدَ بْنِ حَنْبَلٍ ‏ ‏وَإِسْحَقَ ‏ ‏وَيُرْوَى عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ نَامَ عَنْ صَلَاةِ الْعَصْرِ فَاسْتَيْقَظَ عِنْدَ غُرُوبِ الشَّمْسِ فَلَمْ يُصَلِّ حَتَّى غَرَبَتْ الشَّمْسُ ‏ ‏وَقَدْ ذَهَبَ قَوْمٌ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏إِلَى هَذَا ‏ ‏وَأَمَّا أَصْحَابُنَا فَذَهَبُوا إِلَى قَوْلِ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a4397c8b-7c5b-5d79-997b-24dd85ae80af', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '164', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ ابْنِ مَسْعُودٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏إِنَّ الْمُشْرِكِينَ شَغَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَرْبَعِ صَلَوَاتٍ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏حَتَّى ذَهَبَ مِنْ اللَّيْلِ مَا شَاءَ اللَّهُ ‏ ‏فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ ثُمَّ أَقَامَ فَصَلَّى الظُّهْرَ ثُمَّ أَقَامَ فَصَلَّى الْعَصْرَ ثُمَّ أَقَامَ فَصَلَّى الْمَغْرِبَ ثُمَّ أَقَامَ فَصَلَّى الْعِشَاءَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَجَابِرٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَبْدِ اللَّهِ ‏ ‏لَيْسَ بِإِسْنَادِهِ بَأْسٌ ‏ ‏إِلَّا أَنَّ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏لَمْ يَسْمَعْ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَهُوَ الَّذِي اخْتَارَهُ بَعْضُ أَهْلِ الْعِلْمِ فِي الْفَوَائِتِ أَنْ يُقِيمَ الرَّجُلُ لِكُلِّ صَلَاةٍ إِذَا قَضَاهَا وَإِنْ لَمْ يُقِمْ أَجْزَأَهُ وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('95f9714d-a175-570b-bbe7-976f214eef2e', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '165', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ بُنْدَارٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏قَالَ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏وَجَعَلَ يَسُبُّ كُفَّارَ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ مَا كِدْتُ أُصَلِّي الْعَصْرَ حَتَّى تَغْرُبَ الشَّمْسُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ إِنْ صَلَّيْتُهَا قَالَ فَنَزَلْنَا ‏ ‏بُطْحَانَ ‏ ‏فَتَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَوَضَّأْنَا فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ بَعْدَ مَا غَرَبَتْ الشَّمْسُ ثُمَّ صَلَّى بَعْدَهَا الْمَغْرِبَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('644563b3-d195-5ffe-a195-b1a06a4e647a', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '166', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ الْوُسْطَى صَلَاةُ الْعَصْرِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('67565a85-40fd-5433-9aa3-9b630fabce42', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '167', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدَبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ الْوُسْطَى صَلَاةُ الْعَصْرِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَعَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَزَيْدِ بْنِ ثَابِتٍ ‏ ‏وَعَائِشَةَ ‏ ‏وَحَفْصَةَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَأَبِي هَاشِمِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدِيثُ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدَبٍ ‏ ‏حَدِيثٌ صَحِيحٌ ‏ ‏وَقَدْ سَمِعَ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏سَمُرَةَ ‏ ‏فِي صَلَاةِ الْوُسْطَى ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ الْعُلَمَاءِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَغَيْرِهِمْ ‏ ‏و قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَعَائِشَةُ ‏ ‏صَلَاةُ الْوُسْطَى صَلَاةُ الظُّهْرِ ‏ ‏و قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَابْنُ عُمَرَ ‏ ‏صَلَاةُ الْوُسْطَى صَلَاةُ الصُّبْحِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُوسَى مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏قُرَيْشُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏قَالَ قَالَ لِي ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏سَلِ ‏ ‏الْحَسَنَ ‏ ‏مِمَّنْ سَمِعَ حَدِيثَ الْعَقِيقَةِ فَسَأَلْتُهُ فَقَالَ سَمِعْتُهُ مِنْ ‏ ‏سَمُرَةَ بْنِ جُنْدَبٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ الْمَدِينِيِّ ‏ ‏عَنْ ‏ ‏قُرَيْشِ بْنِ أَنَسٍ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏وَسَمَاعُ ‏ ‏الْحَسَنِ ‏ ‏مِنْ ‏ ‏سَمُرَةَ ‏ ‏صَحِيحٌ وَاحْتَجَّ بِهَذَا الْحَدِيثِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3759f5ab-c7aa-50e4-b1a6-5cc4447e16fa', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '168', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ وَهُوَ ابْنُ زَاذَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَال سَمِعْتُ ‏ ‏غَيْرَ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَكَانَ مِنْ أَحَبِّهِمْ إِلَيَّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصَّلَاةِ بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ وَعَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَابْنِ مَسْعُودٍ ‏ ‏وَعُقْبَةَ بْنِ عَامِرٍ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَابْنِ عُمَرَ ‏ ‏وَسَمُرَةَ بْنِ جُنْدَبٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَمُعَاذِ ابْنِ عَفْرَاءَ ‏ ‏وَالصُّنَابِحِيِّ ‏ ‏وَلَمْ يَسْمَعْ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏وَزَيْدِ بْنِ ثَابِتٍ ‏ ‏وَعَائِشَةَ ‏ ‏وَكَعْبِ بْنِ مُرَّةَ ‏ ‏وَأَبِي أُمَامَةَ ‏ ‏وَعَمْرِو بْنِ عَبَسَةَ ‏ ‏وَيَعْلَى بْنِ أُمَيَّةَ ‏ ‏وَمُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ الْفُقَهَاءِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ أَنَّهُمْ كَرِهُوا الصَّلَاةَ بَعْدَ صَلَاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ صَلَاةِ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَأَمَّا الصَّلَوَاتُ الْفَوَائِتُ فَلَا بَأْسَ أَنْ ‏ ‏تُقْضَى بَعْدَ الْعَصْرِ وَبَعْدَ الصُّبْحِ ‏ ‏قَالَ ‏ ‏عَلِيُّ ابْنُ الْمَدِينِيِّ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ يَسْمَعْ ‏ ‏قَتَادَةُ ‏ ‏مِنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏إِلَّا ثَلَاثَةَ أَشْيَاءَ ‏ ‏حَدِيثَ ‏ ‏عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏ ‏وَحَدِيثَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْبَغِي لِأَحَدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏وَحَدِيثَ ‏ ‏عَلِيٍّ ‏ ‏الْقُضَاةُ ثَلَاثَةٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb189d65-edb2-5010-9e9c-e5a08debc26f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '169', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ لِأَنَّهُ أَتَاهُ مَالٌ فَشَغَلَهُ عَنْ الرَّكْعَتَيْنِ بَعْدَ الظُّهْرِ فَصَلَّاهُمَا بَعْدَ الْعَصْرِ ثُمَّ لَمْ يَعُدْ لَهُمَا ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏وَمَيْمُونَةَ ‏ ‏وَأَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَقَدْ رَوَى غَيْرُ وَاحِدٍ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ صَلَّى بَعْدَ الْعَصْرِ رَكْعَتَيْنِ وَهَذَا خِلَافُ مَا رُوِيَ عَنْهُ أَنَّهُ نَهَى عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏ ‏وَحَدِيثُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَصَحُّ ‏ ‏حَيْثُ قَالَ لَمْ يَعُدْ لَهُمَا ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏نَحْوُ حَدِيثِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي هَذَا الْبَابِ رِوَايَاتٌ رُوِيَ عَنْهَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا دَخَلَ عَلَيْهَا بَعْدَ الْعَصْرِ إِلَّا صَلَّى رَكْعَتَيْنِ ‏ ‏وَرُوِيَ ‏ ‏عَنْهَا ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏ ‏وَالَّذِي اجْتَمَعَ عَلَيْهِ أَكْثَرُ أَهْلِ الْعِلْمِ عَلَى كَرَاهِيَةِ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ إِلَّا مَا اسْتُثْنِيَ مِنْ ذَلِكَ مِثْلُ الصَّلَاةِ ‏ ‏بِمَكَّةَ ‏ ‏بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَبَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ بَعْدَ الطَّوَافِ فَقَدْ رُوِيَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُخْصَةٌ فِي ذَلِكَ وَقَدْ قَالَ بِهِ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ وَبِهِ يَقُولُ ‏ ‏الشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏وَقَدْ كَرِهَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ الصَّلَاةَ ‏ ‏بِمَكَّةَ ‏ ‏أَيْضًا بَعْدَ الْعَصْرِ وَبَعْدَ الصُّبْحِ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَمَالِكُ بْنُ أَنَسٍ ‏ ‏وَبَعْضُ أَهْلِ ‏ ‏الْكُوفَةِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
