insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('03595d66-5682-5bee-a218-aa79fa27d763', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '171', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏وَعَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏وَعَنْ ‏ ‏الْأَعْرَجِ ‏ ‏يُحَدِّثُونَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ مِنْ الصُّبْحِ رَكْعَةً قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ الصُّبْحَ وَمَنْ أَدْرَكَ مِنْ الْعَصْرِ رَكْعَةً قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ الْعَصْرَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَبِهِ يَقُولُ أَصْحَابُنَا ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏وَمَعْنَى هَذَا الْحَدِيثِ عِنْدَهُمْ لِصَاحِبِ الْعُذْرِ مِثْلُ الرَّجُلِ الَّذِي يَنَامُ عَنْ الصَّلَاةِ أَوْ ‏ ‏يَنْسَاهَا فَيَسْتَيْقِظُ وَيَذْكُرُ عِنْدَ طُلُوعِ الشَّمْسِ وَعِنْدَ غُرُوبِهَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('197ddf37-c8ad-55df-89a1-d4e3915435ed', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '172', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الظُّهْرِ وَالْعَصْرِ وَبَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِالْمَدِينَةِ ‏ ‏مِنْ غَيْرِ خَوْفٍ وَلَا مَطَرٍ ‏ ‏قَالَ ‏ ‏فَقِيلَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏مَا أَرَادَ بِذَلِكَ قَالَ أَرَادَ أَنْ ‏ ‏لَا يُحْرِجَ أُمَّتَهُ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَدْ رُوِيَ عَنْهُ مِنْ غَيْرِ وَجْهٍ ‏ ‏رَوَاهُ ‏ ‏جَابِرُ بْنُ زَيْدٍ ‏ ‏وَسَعِيدُ بْنُ جُبَيْرٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ شَقِيقٍ الْعُقَيْلِيُّ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرُ هَذَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1da02877-c3c8-5dd2-8c31-1590d0d13a31', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '173', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ يَحْيَى بْنُ خَلَفٍ الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَمَعَ بَيْنَ الصَّلَاتَيْنِ مِنْ غَيْرِ عُذْرٍ فَقَدْ أَتَى بَابًا مِنْ أَبْوَابِ الْكَبَائِرِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَنَشٌ ‏ ‏هَذَا هُوَ ‏ ‏أَبُو عَلِيٍّ الرَّحَبِيُّ ‏ ‏وَهُوَ ‏ ‏حُسَيْنُ بْنُ قَيْسٍ ‏ ‏وَهُوَ ضَعِيفٌ عِنْدَ أَهْلِ الْحَدِيثِ ضَعَّفَهُ ‏ ‏أَحْمَدُ ‏ ‏وَغَيْرُهُ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ أَنْ لَا يَجْمَعَ بَيْنَ الصَّلَاتَيْنِ إِلَّا فِي السَّفَرِ أَوْ ‏ ‏بِعَرَفَةَ ‏ ‏وَرَخَّصَ بَعْضُ أَهْلِ الْعِلْمِ مِنْ التَّابِعِينَ فِي الْجَمْعِ بَيْنَ الصَّلَاتَيْنِ لِلْمَرِيضِ وَبِهِ يَقُولُ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ يَجْمَعُ بَيْنَ الصَّلَاتَيْنِ فِي الْمَطَرِ وَبِهِ يَقُولُ ‏ ‏الشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏وَلَمْ يَرَ ‏ ‏الشَّافِعِيُّ ‏ ‏لِلْمَرِيضِ أَنْ يَجْمَعَ بَيْنَ الصَّلَاتَيْنِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9cc0faa2-a346-5ce5-a848-f26f9b34a220', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '174', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْأُمَوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا أَصْبَحْنَا أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِالرُّؤْيَا فَقَالَ ‏ ‏إِنَّ هَذِهِ لَرُؤْيَا حَقٍّ فَقُمْ مَعَ ‏ ‏بِلَالٍ ‏ ‏فَإِنَّهُ ‏ ‏أَنْدَى ‏ ‏وَأَمَدُّ صَوْتًا مِنْكَ فَأَلْقِ عَلَيْهِ مَا قِيلَ لَكَ وَلْيُنَادِ بِذَلِكَ قَالَ فَلَمَّا سَمِعَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏نِدَاءَ ‏ ‏بِلَالٍ ‏ ‏بِالصَّلَاةِ خَرَجَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَجُرُّ إِزَارَهُ وَهُوَ يَقُولُ يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ رَأَيْتُ مِثْلَ الَّذِي قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلِلَّهِ الْحَمْدُ فَذَلِكَ أَثْبَتُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رَوَى هَذَا الْحَدِيثَ ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏أَتَمَّ مِنْ هَذَا الْحَدِيثِ وَأَطْوَلَ وَذَكَرَ فِيهِ قِصَّةَ الْأَذَانِ مَثْنَى مَثْنَى وَالْإِقَامَةِ مَرَّةً مَرَّةً ‏ ‏وَعَبْدُ اللَّهِ بْنُ زَيْدٍ هُوَ ابْنُ عَبْدِ رَبِّهِ ‏ ‏وَيُقَالُ ‏ ‏ابْنُ عَبْدِ رَبٍّ ‏ ‏وَلَا نَعْرِفُ لَهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا يَصِحُّ إِلَّا هَذَا الْحَدِيثَ الْوَاحِدَ فِي الْأَذَانِ ‏ ‏وَعَبْدُ اللَّهِ بْنُ زَيْدِ بْنِ عَاصِمٍ الْمَازِنِيُّ ‏ ‏لَهُ أَحَادِيثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَمُّ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b3582ee-a597-5585-be01-4ce7d02da548', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '175', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ النَّضْرِ بْنِ أَبِي النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ الْمُسْلِمُونَ حِينَ قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏يَجْتَمِعُونَ ‏ ‏فَيَتَحَيَّنُونَ ‏ ‏الصَّلَوَاتِ وَلَيْسَ ‏ ‏يُنَادِي بِهَا أَحَدٌ فَتَكَلَّمُوا يَوْمًا فِي ذَلِكَ فَقَالَ بَعْضُهُمْ اتَّخِذُوا ‏ ‏نَاقُوسًا ‏ ‏مِثْلَ ‏ ‏نَاقُوسِ ‏ ‏النَّصَارَى ‏ ‏وَقَالَ بَعْضُهُمْ اتَّخِذُوا ‏ ‏قَرْنًا ‏ ‏مِثْلَ ‏ ‏قَرْنِ ‏ ‏الْيَهُودِ ‏ ‏قَالَ فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَوَلَا تَبْعَثُونَ رَجُلًا يُنَادِي بِالصَّلَاةِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بِلَالُ ‏ ‏قُمْ ‏ ‏فَنَادِ ‏ ‏بِالصَّلَاةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ ‏ ‏مِنْ حَدِيثِ ‏ ‏ابْنِ عُمَرَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e9b42138-2c91-52cb-accc-53fd3533ce56', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '176', '‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ مُعَاذٍ الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ الْعَزِيزِ بْنِ عَبْدِ الْمَلِكِ بْنِ أَبِي مَحْذُورَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏وَجَدِّي ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي مَحْذُورَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْعَدَهُ وَأَلْقَى عَلَيْهِ الْأَذَانَ حَرْفًا حَرْفًا ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏مِثْلَ أَذَانِنَا ‏ ‏قَالَ ‏ ‏بِشْرٌ ‏ ‏فَقُلْتُ لَهُ أَعِدْ عَلَيَّ فَوَصَفَ الْأَذَانَ ‏ ‏بِالتَّرْجِيعِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي مَحْذُورَةَ ‏ ‏فِي الْأَذَانِ ‏ ‏حَدِيثٌ صَحِيحٌ ‏ ‏وَقَدْ رُوِيَ عَنْهُ مِنْ غَيْرِ وَجْهٍ وَعَلَيْهِ الْعَمَلُ ‏ ‏بِمَكَّةَ ‏ ‏وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('abf0ba53-52c3-5215-ac1c-f354553ce349', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '177', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُوسَى مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ الْوَاحِدِ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏أَبِي مَحْذُورَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَّمَهُ الْأَذَانَ تِسْعَ عَشْرَةَ كَلِمَةً وَالْإِقَامَةَ سَبْعَ عَشْرَةَ كَلِمَةً ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَأَبُو مَحْذُورَةَ ‏ ‏اسْمُهُ ‏ ‏سَمُرَةُ بْنُ مِعْيَرٍ ‏ ‏وَقَدْ ذَهَبَ بَعْضُ أَهْلِ الْعِلْمِ إِلَى هَذَا فِي الْأَذَانِ وَقَدْ رُوِيَ عَنْ ‏ ‏أَبِي مَحْذُورَةَ ‏ ‏أَنَّهُ كَانَ يُفْرِدُ الْإِقَامَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4b343b4a-f238-5079-9985-5d21a06e9316', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '178', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏وَيَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَيُوتِرَ الْإِقَامَةَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏أَنَسٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ بَعْضِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَبِهِ يَقُولُ ‏ ‏مَالِكٌ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('db767aac-1ada-5c03-bb9a-afc1b7bdfb47', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '179', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ الْأَشَجُّ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏كَانَ أَذَانُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَفْعًا ‏ ‏شَفْعًا ‏ ‏فِي الْأَذَانِ وَالْإِقَامَةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏رَوَاهُ ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَصْحَابُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدٍ ‏ ‏رَأَى الْأَذَانَ فِي الْمَنَامِ ‏ ‏و قَالَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدٍ ‏ ‏رَأَى الْأَذَانَ فِي الْمَنَامِ ‏ ‏وَهَذَا ‏ ‏أَصَحُّ ‏ ‏مِنْ حَدِيثِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ أَبِي لَيْلَى ‏ ‏لَمْ يَسْمَعْ مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ الْأَذَانُ مَثْنَى مَثْنَى وَالْإِقَامَةُ مَثْنَى مَثْنَى وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَأَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏هُوَ ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏كَانَ قَاضِيَ ‏ ‏الْكُوفَةِ ‏ ‏وَلَمْ يَسْمَعْ مِنْ أَبِيهِ شَيْئًا إِلَّا أَنَّهُ ‏ ‏يَرْوِي عَنْ رَجُلٍ عَنْ أَبِيهِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d78a92d2-5c1d-5241-8d88-d10916cf2a01', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '180', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمُنْعِمِ ‏ ‏هُوَ صَاحِبُ السِّقَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَعَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِبِلَالٍ ‏ ‏يَا ‏ ‏بِلَالُ ‏ ‏إِذَا أَذَّنْتَ ‏ ‏فَتَرَسَّلْ ‏ ‏فِي أَذَانِكَ وَإِذَا أَقَمْتَ ‏ ‏فَاحْدُرْ ‏ ‏وَاجْعَلْ بَيْنَ أَذَانِكَ وَإِقَامَتِكَ قَدْرَ مَا يَفْرُغُ الْآكِلُ مِنْ أَكْلِهِ وَالشَّارِبُ مِنْ شُرْبِهِ ‏ ‏وَالْمُعْتَصِرُ ‏ ‏إِذَا دَخَلَ لِقَضَاءِ حَاجَتِهِ وَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمُنْعِمِ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏جَابِرٍ ‏ ‏هَذَا ‏ ‏حَدِيثٌ لَا نَعْرِفُهُ إِلَّا مِنْ هَذَا الْوَجْهِ مِنْ حَدِيثِ ‏ ‏عَبْدِ الْمُنْعِمِ ‏ ‏وَهُوَ إِسْنَادٌ مَجْهُولٌ ‏ ‏وَعَبْدُ الْمُنْعِمِ ‏ ‏شَيْخٌ بَصْرِيٌّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadith_books (id, slug, name_ar, name_en, source, author_ar, author_en, hadith_count) values ('f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', 'nasai', 'سنن النسائي', 'Sunan al-Nasa''i', 'Open-Hadith-Data (ODbL/DbCL)', 'الإمام النسائي', 'Imam al-Nasa''i', 5663) on conflict (slug) do update set name_ar=excluded.name_ar, name_en=excluded.name_en, source=excluded.source, author_ar=excluded.author_ar, author_en=excluded.author_en, hadith_count=excluded.hadith_count;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f460c131-857b-50f3-808e-c72c1215965f', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '1', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلَا يَغْمِسْ يَدَهُ فِي وَضُوئِهِ حَتَّى يَغْسِلَهَا ثَلَاثًا فَإِنَّ أَحَدَكُمْ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ef9989cd-10aa-5df0-98cd-ec2405ed0cb4', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '2', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ ‏ ‏يَشُوصُ ‏ ‏فَاهُ بِالسِّوَاكِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ee951c4b-73a1-5bed-af97-f1b0c0bed49c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '3', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَسْتَنُّ ‏ ‏وَطَرَفُ السِّوَاكِ عَلَى لِسَانِهِ وَهُوَ يَقُولُ ‏ ‏عَأْ ‏ ‏عَأْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9dc2f469-608f-523f-ab5c-4fe212bea0eb', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '4', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى وَهُوَ ابْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قُرَّةُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَقْبَلْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعِي رَجُلَانِ مِنْ ‏ ‏الْأَشْعَرِيِّينَ ‏ ‏أَحَدُهُمَا عَنْ يَمِينِي وَالْآخَرُ عَنْ يَسَارِي وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَاكُ فَكِلَاهُمَا سَأَلَ الْعَمَلَ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ نَبِيًّا مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ فَكَأَنِّي أَنْظُرُ إِلَى سِوَاكِهِ تَحْتَ شَفَتِهِ ‏ ‏قَلَصَتْ ‏ ‏فَقَالَ إِنَّا ‏ ‏لَا أَوْ ‏ ‏لَنْ نَسْتَعِينَ عَلَى الْعَمَلِ مَنْ أَرَادَهُ وَلَكِنْ اذْهَبْ أَنْتَ فَبَعَثَهُ عَلَى ‏ ‏الْيَمَنِ ‏ ‏ثُمَّ ‏ ‏أَرْدَفَهُ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9c861c59-425d-5b2c-93ce-1d86059f4756', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '5', '‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏يَزِيدَ وَهُوَ ابْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَتِيقٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b7b46b89-8b32-514d-b15c-1d9f60991c5f', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '6', '‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏وَعِمْرَانُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ الْحَبْحَابِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَكْثَرْتُ عَلَيْكُمْ فِي السِّوَاكِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('42ef3208-7542-5419-8b4a-2ae382ad2208', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '7', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('df8b40b1-43bf-5f60-a381-cbd45ae932e5', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '8', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ خَشْرَمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى وَهُوَ ابْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ وَهُوَ ابْنُ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏بِأَيِّ شَيْءٍ كَانَ يَبْدَأُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ بَيْتَهُ قَالَتْ بِالسِّوَاكِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b82e00b-5363-5b3e-b1e4-59fc004e6822', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '9', '‏ ‏أَخْبَرَنَا ‏ ‏الْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْفِطْرَةُ خَمْسٌ ‏ ‏الِاخْتِتَانُ ‏ ‏وَالِاسْتِحْدَادُ ‏ ‏وَقَصُّ الشَّارِبِ وَتَقْلِيمُ الْأَظْفَارِ وَنَتْفُ الْإِبْطِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('46d8a50c-6279-55f7-80f3-d787a082737f', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '10', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَعْمَرًا ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسٌ مِنْ الْفِطْرَةِ قَصُّ الشَّارِبِ وَنَتْفُ الْإِبْطِ وَتَقْلِيمُ الْأَظْفَارِ ‏ ‏وَالِاسْتِحْدَادُ ‏ ‏وَالْخِتَانُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bd363136-8cc7-5b83-83db-5aee269af8f8', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '11', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ مِنْ الْفِطْرَةِ ‏ ‏الْخِتَانُ ‏ ‏وَحَلْقُ الْعَانَةِ وَنَتْفُ الْإِبْطِ وَتَقْلِيمُ الْأَظْفَارِ وَأَخْذُ الشَّارِبِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0e5e821a-e9b6-5ee0-9a30-f6288b2ef349', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '12', '‏ ‏أَخْبَرَنَا ‏ ‏الْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْفِطْرَةُ قَصُّ الْأَظْفَارِ وَأَخْذُ الشَّارِبِ وَحَلْقُ الْعَانَةِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c7e26d55-cae6-5e42-8c6f-c9d3268d6290', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '13', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَأْخُذْ شَارِبَهُ فَلَيْسَ مِنَّا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c0b05bc2-d6da-5a69-b17b-48fa4496c0ba', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '14', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرٌ هُوَ ابْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏وَقَّتَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَصِّ الشَّارِبِ وَتَقْلِيمِ الْأَظْفَارِ وَحَلْقِ الْعَانَةِ وَنَتْفِ الْإِبْطِ أَنْ لَا نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ يَوْمًا وَقَالَ مَرَّةً أُخْرَى أَرْبَعِينَ لَيْلَةً ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('02a63d56-9b2a-5f72-9e31-3d2e1be6ec84', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '15', '‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحْفُوا ‏ ‏الشَّوَارِبَ وَأَعْفُوا اللِّحَى ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fbe5ba74-94e9-5015-9793-de003df91c16', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '16', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْخَطْمِيُّ عُمَيْرُ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ فُضَيْلٍ ‏ ‏وَعُمَارَةُ بْنُ خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي قُرَادٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْخَلَاءِ وَكَانَ ‏ ‏إِذَا أَرَادَ الْحَاجَةَ أَبْعَدَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('381eecd7-65de-52d7-b501-e606e42cb2e2', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '17', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ذَهَبَ الْمَذْهَبَ أَبْعَدَ قَالَ فَذَهَبَ لِحَاجَتِهِ وَهُوَ فِي بَعْضِ أَسْفَارِهِ فَقَالَ ائْتِنِي بِوَضُوءٍ فَأَتَيْتُهُ بِوَضُوءٍ فَتَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ ‏ ‏قَالَ الشَّيْخُ ‏ ‏إِسْمَعِيلُ ‏ ‏هُوَ ‏ ‏ابْنُ جَعْفَرِ بْنِ أَبِي كَثِيرٍ الْقَارِئُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('25f771dd-a637-507b-9329-66fa67139a78', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '18', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَانْتَهَى إِلَى ‏ ‏سُبَاطَةِ ‏ ‏قَوْمٍ ‏ ‏فَبَالَ قَائِمًا فَتَنَحَّيْتُ عَنْهُ فَدَعَانِي وَكُنْتُ عِنْدَ ‏ ‏عَقِبَيْهِ ‏ ‏حَتَّى فَرَغَ ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('259ba245-b92e-5a5a-a528-d0707e998018', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '19', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْخَلَاءَ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبُثِ ‏ ‏وَالْخَبَائِثِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a05eb0d3-ceea-5204-a8cb-c4600015b0b5', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '20', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏ابْنِ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ إِسْحَقَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏وَهُوَ ‏ ‏بِمِصْرَ ‏ ‏يَقُولُ ‏ ‏وَاللَّهِ مَا أَدْرِي كَيْفَ أَصْنَعُ بِهَذِهِ ‏ ‏الْكَرَايِيسِ ‏ ‏وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْغَائِطِ أَوْ الْبَوْلِ فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَا يَسْتَدْبِرْهَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a29bf50-2dcd-5d2d-8c86-31fba9526b64', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '21', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا تَسْتَدْبِرُوهَا لِغَائِطٍ أَوْ بَوْلٍ وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c24bf298-1326-5743-8dfb-f4048d5ede32', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '22', '‏ ‏أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ الْغَائِطَ فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَكِنْ لِيُشَرِّقْ أَوْ لِيُغَرِّبْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dba02b28-cdbe-5170-a585-dd55c56b538a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '23', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقَدْ ارْتَقَيْتُ عَلَى ظَهْرِ بَيْتِنَا ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى لَبِنَتَيْنِ مُسْتَقْبِلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏لِحَاجَتِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('580ffc48-d8a9-5865-afc6-fed2b8450ff3', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '24', '‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ دُرُسْتَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو إِسْمَعِيلَ وَهُوَ الْقَنَّادُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا بَالَ أَحَدُكُمْ فَلَا يَأْخُذْ ذَكَرَهُ بِيَمِينِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c4f5cdc6-21bd-5926-9bb0-ef240a8fdd0c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '25', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى هُوَ ابْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْخَلَاءَ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('31bdf4bb-25ff-5017-b93b-db0f6ebb340e', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '26', '‏ ‏أَخْبَرَنَا ‏ ‏مُؤَمَّلُ بْنُ هِشَامٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى ‏ ‏سُبَاطَةَ ‏ ‏قَوْمٍ فَبَالَ قَائِمًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3a2c8db-4183-500d-8467-15adcde68829', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '27', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏أَنَّ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى ‏ ‏سُبَاطَةَ ‏ ‏قَوْمٍ فَبَالَ قَائِمًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4861b4d0-d77d-5182-a6a1-1806a3bc60dc', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '28', '‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَشَى إِلَى ‏ ‏سُبَاطَةِ ‏ ‏قَوْمٍ فَبَالَ قَائِمًا ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فِي حَدِيثِهِ وَمَسَحَ عَلَى خُفَّيْهِ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏مَنْصُورٌ ‏ ‏الْمَسْحَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('29cbe841-a313-5b4a-a3f7-006101a46f33', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '29', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَنْ حَدَّثَكُمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ قَائِمًا فَلَا تُصَدِّقُوهُ ‏ ‏مَا كَانَ يَبُولُ إِلَّا جَالِسًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6bd26f08-da85-5e4f-97f7-103d8e85e94d', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '30', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ابْنِ حَسَنَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي يَدِهِ كَهَيْئَةِ ‏ ‏الدَّرَقَةِ ‏ ‏فَوَضَعَهَا ثُمَّ جَلَسَ خَلْفَهَا فَبَالَ إِلَيْهَا فَقَالَ بَعْضُ الْقَوْمِ انْظُرُوا يَبُولُ كَمَا تَبُولُ الْمَرْأَةُ فَسَمِعَهُ فَقَالَ ‏ ‏أَوَ مَا عَلِمْتَ مَا أَصَابَ صَاحِبُ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانُوا إِذَا أَصَابَهُمْ شَيْءٌ مِنْ الْبَوْلِ ‏ ‏قَرَضُوهُ ‏ ‏بِالْمَقَارِيضِ ‏ ‏فَنَهَاهُمْ صَاحِبُهُمْ فَعُذِّبَ فِي قَبْرِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7637fcb5-579f-516e-9274-6ef5d7455e93', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '31', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرَيْنِ فَقَالَ ‏ ‏إِنَّهُمَا يُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا هَذَا فَكَانَ لَا ‏ ‏يَسْتَنْزِهُ ‏ ‏مِنْ بَوْلِهِ وَأَمَّا هَذَا فَإِنَّهُ كَانَ يَمْشِي ‏ ‏بِالنَّمِيمَةِ ‏ ‏ثُمَّ دَعَا ‏ ‏بِعَسِيبٍ ‏ ‏رَطْبٍ فَشَقَّهُ بِاثْنَيْنِ فَغَرَسَ عَلَى هَذَا وَاحِدًا وَعَلَى هَذَا وَاحِدًا ثُمَّ قَالَ لَعَلَّهُ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا ‏ ‏خَالَفَهُ ‏ ‏مَنْصُورٌ ‏ ‏رَوَاهُ عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏طَاوُسًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9ede734b-f9ea-5452-a092-682d65885459', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '32', '‏ ‏أَخْبَرَنَا ‏ ‏أَيَّوبُ بْنُ مُحَمَّدٍ الْوَزَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَتْنِي ‏ ‏حُكَيْمَةُ بِنْتُ أُمَيْمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهَا ‏ ‏أُمَيْمَةَ بِنْتِ رُقَيْقَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدَحٌ مِنْ ‏ ‏عَيْدَانٍ يَبُولُ فِيهِ وَيَضَعُهُ تَحْتَ السَّرِيرِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('54e10054-10ac-5eb3-8363-aab98468d4f6', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '33', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَزْهَرُ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏يَقُولُونَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْصَى إِلَى ‏ ‏عَلِيٍّ ‏ ‏لَقَدْ دَعَا ‏ ‏بِالطَّسْتِ ‏ ‏لِيَبُولَ فِيهَا ‏ ‏فَانْخَنَثَتْ ‏ ‏نَفْسُهُ وَمَا أَشْعُرُ فَإِلَى مَنْ أَوْصَى ‏ ‏قَالَ الشَّيْخُ ‏ ‏أَزْهَرُ ‏ ‏هُوَ ‏ ‏ابْنُ سَعْدٍ السَّمَّانُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('15ede7fc-d7be-5310-a7de-af3f1d755192', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '34', '‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَرْجِسَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي جُحْرٍ ‏ ‏قَالُوا ‏ ‏لِقَتَادَةَ ‏ ‏وَمَا يُكْرَهُ مِنْ الْبَوْلِ فِي الْجُحْرِ قَالَ يُقَالُ إِنَّهَا مَسَاكِنُ الْجِنِّ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ffe42645-7f26-5b61-9bd0-a1f0250d7739', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '35', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ الْبَوْلِ فِي الْمَاءِ الرَّاكِدِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6f0d800c-04d4-5399-a220-3db05baaab90', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '36', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي مُسْتَحَمِّهِ فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('44e82da0-06e4-586f-9472-8208b9c156d8', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '37', '‏ ‏أَخْبَرَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏وَقَبِيصَةُ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّ رَجُلٌ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ السَّلَامَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a55e3bef-b682-5e1c-b7a6-f3b61ff7d498', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '38', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏حُضَيْنٍ أَبِي سَاسَانَ ‏ ‏عَنْ ‏ ‏الْمُهَاجِرِ بْنِ قُنْفُذٍ ‏ ‏أَنَّهُ ‏ ‏سَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَبُولُ فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ فَلَمَّا تَوَضَّأَ رَدَّ عَلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ce141f3-13c9-58a9-adae-0212bf8554e4', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '39', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ بْنِ سَنَّةَ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَسْتَطِيبَ ‏ ‏أَحَدُكُمْ بِعَظْمٍ أَوْ ‏ ‏رَوْثٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ce5657f2-bcb6-5321-87bc-ee0902d78f92', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '40', '‏ ‏أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِى ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْقَعْقَاعُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّمَا أَنَا لَكُمْ مِثْلُ الْوَالِدِ أُعَلِّمُكُمْ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْخَلَاءِ فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَا يَسْتَدْبِرْهَا وَلَا ‏ ‏يَسْتَنْجِ ‏ ‏بِيَمِينِهِ وَكَانَ يَأْمُرُ بِثَلَاثَةِ أَحْجَارٍ وَنَهَى عَنْ ‏ ‏الرَّوْثِ ‏ ‏وَالرِّمَّةِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('57902c6c-5c92-5203-b19a-acb9dfa4f003', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '41', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏قَالَ لَهُ رَجُلٌ إِنَّ صَاحِبَكُمْ لَيُعَلِّمُكُمْ حَتَّى ‏ ‏الْخِرَاءَةَ ‏ ‏قَالَ أَجَلْ ‏ ‏نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِغَائِطٍ أَوْ بَوْلٍ أَوْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِأَيْمَانِنَا أَوْ نَكْتَفِيَ بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f81b8316-df47-52a4-b410-fd23c6afc5db', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '42', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏قَالَ لَيْسَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ذَكَرَهُ وَلَكِنْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَقُولُ ‏ ‏أَتَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَائِطَ ‏ ‏وَأَمَرَنِي أَنْ آتِيَهُ بِثَلَاثَةِ أَحْجَارٍ فَوَجَدْتُ حَجَرَيْنِ وَالْتَمَسْتُ الثَّالِثَ فَلَمْ أَجِدْهُ فَأَخَذْتُ ‏ ‏رَوْثَةً ‏ ‏فَأَتَيْتُ بِهِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ هَذِهِ ‏ ‏رِكْسٌ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏الرِّكْسُ طَعَامُ الْجِنِّ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92599431-cbeb-544c-b355-65b717add752', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '43', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('46370988-25ef-5d24-8be8-bc48d8e41854', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '44', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ قُرْطٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ إِلَى ‏ ‏الْغَائِطِ ‏ ‏فَلْيَذْهَبْ مَعَهُ بِثَلَاثَةِ أَحْجَارٍ ‏ ‏فَلْيَسْتَطِبْ ‏ ‏بِهَا فَإِنَّهَا تَجْزِي عَنْهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d5fd4cf4-e299-57cd-83f9-23fd22cd639a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '45', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏النَّضْرُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْخَلَاءَ أَحْمِلُ أَنَا ‏ ‏وَغُلَامٌ ‏ ‏مَعِي نَحْوِي ‏ ‏إِدَاوَةً ‏ ‏مِنْ مَاءٍ ‏ ‏فَيَسْتَنْجِي بِالْمَاءِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('00e73ff1-267d-5b12-bc6c-cdca547d0342', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '46', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ أَنْ ‏ ‏يَسْتَطِيبُوا ‏ ‏بِالْمَاءِ فَإِنِّي ‏ ‏أَسْتَحْيِيهِمْ مِنْهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('14b56a76-96c2-563a-aa53-416a34dab185', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '47', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ مَسْعُودٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي إِنَائِهِ وَإِذَا أَتَى الْخَلَاءَ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَلَا ‏ ‏يَتَمَسَّحْ ‏ ‏بِيَمِينِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b84c97aa-e7bc-5564-be44-8c543c30573f', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '48', '‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏يِحْيَى بْنِ أَبِى كَثِيرٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَتَنَفَّسَ فِي الْإِنَاءِ وَأَنْ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَأَنْ ‏ ‏يَسْتَطِيبَ ‏ ‏بِيَمِينِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4811105c-5e31-5c91-ae71-1ce2d6650e69', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '49', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏وَشُعَيْبُ بْنُ يُوسُفَ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفَيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏قَالَ الْمُشْرِكُونَ إِنَّا ‏ ‏لَنَرَى صَاحِبَكُمْ يُعَلِّمُكُمْ ‏ ‏الْخِرَاءَةَ ‏ ‏قَالَ أَجَلْ ‏ ‏نَهَانَا أَنْ ‏ ‏يَسْتَنْجِيَ ‏ ‏أَحَدُنَا بِيَمِينِهِ وَيَسْتَقْبِلَ الْقِبْلَةَ وَقَالَ لَا ‏ ‏يَسْتَنْجِي ‏ ‏أَحَدُكُمْ بِدُونِ ثَلَاثَةِ أَحْجَارٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6546549c-dd16-5388-a3f2-17e70f9e0ef9', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '50', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمُبَارَكِ الْمُخَرِّمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَلَمَّا ‏ ‏اسْتَنْجَى ‏ ‏دَلَكَ يَدَهُ بِالْأَرْضِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('709c8a22-9252-549a-97e4-52aeba227c4c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '51', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبٌ يَعْنِي ابْنَ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ بْنُ عَبْدِ اللَّهِ الْبَجَلِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى الْخَلَاءَ فَقَضَى الْحَاجَةَ ثُمَّ قَالَ يَا ‏ ‏جَرِيرُ ‏ ‏هَاتِ طَهُورًا فَأَتَيْتُهُ بِالْمَاءِ ‏ ‏فَاسْتَنْجَى ‏ ‏بِالْمَاءِ وَقَالَ بِيَدِهِ فَدَلَكَ بِهَا الْأَرْضَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا أَشْبَهُ بِالصَّوَابِ مِنْ حَدِيثِ ‏ ‏شَرِيكٍ ‏ ‏وَاللَّهُ سُبْحَانَهُ وَتَعَالَى أَعْلَمُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c64701c-6d2c-50c4-8146-470589387a1b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '52', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏وَالْحُسَيْنُ بْنُ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمَاءِ وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ ‏ ‏إِذَا كَانَ الْمَاءُ ‏ ‏قُلَّتَيْنِ ‏ ‏لَمْ يَحْمِلْ ‏ ‏الْخَبَثَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('46288968-9d51-5e39-946e-068f90081d80', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '53', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ أَعْرَابِيًّا بَالَ فِي الْمَسْجِدِ فَقَامَ عَلَيْهِ بَعْضُ الْقَوْمِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهُ لَا ‏ ‏تُزْرِمُوهُ ‏ ‏فَلَمَّا فَرَغَ دَعَا بِدَلْوٍ فَصَبَّهُ عَلَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏يَعْنِي لَا تَقْطَعُوا عَلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1304c621-e78a-548c-b3e0-bb7bb95b52df', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '54', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏بَالَ أَعْرَابِيُّ فِي الْمَسْجِدِ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِدَلْوٍ مِنْ مَاءٍ فَصُبَّ عَلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6b8a28f-0c93-5d10-a697-ba51af1e06ec', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '55', '‏ ‏أَخْبَرَنَا ‏ ‏سُوَيْدُ بْنُ نَصْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى الْمَسْجِدِ فَبَالَ فَصَاحَ بِهِ النَّاسُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتْرُكُوهُ فَتَرَكُوهُ حَتَّى بَالَ ثُمَّ أَمَرَ بِدَلْوٍ فَصُبَّ عَلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('638a12eb-caf2-50cb-800c-98ee432e730f', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '56', '‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَامَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ فَتَنَاوَلَهُ النَّاسُ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهُ ‏ ‏وَأَهْرِيقُوا ‏ ‏عَلَى بَوْلِهِ دَلْوًا مِنْ مَاءٍ فَإِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ وَلَمْ تُبْعَثُوا مُعَسِّرِينَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8f446f2f-cfb0-511a-838f-6e564f351d9d', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '57', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَتَوَضَّأُ مِنْهُ ‏ ‏قَالَ ‏ ‏عَوْفٌ ‏ ‏وَقَالَ ‏ ‏خِلَاسٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eaeed014-3545-51d8-a514-2195f28356a5', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '58', '‏ ‏أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَتِيقٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَغْتَسِلُ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏كَانَ ‏ ‏يَعْقُوبُ ‏ ‏لَا يُحَدِّثُ بِهَذَا الْحَدِيثِ إِلَّا بِدِينَارٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0b41f50f-52eb-5935-9a03-5ba1b29dc85f', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '59', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ أَبِي بُرْدَةَ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الدَّارِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنْ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e53a83fa-f4f2-5c23-986a-d3a53ffe85b1', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '60', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَفْتَحَ الصَّلَاةَ سَكَتَ هُنَيْهَةً فَقُلْتُ بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ مَا تَقُولُ فِي سُكُوتِكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ قَالَ أَقُولُ ‏ ‏اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنْ ‏ ‏الدَّنَسِ ‏ ‏اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1fa8cd9a-44dd-59a3-81f8-5892fb5955a8', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '61', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ اغْسِلْ خَطَايَايَ بِمَاءِ الثَّلْجِ وَالْبَرَدِ وَنَقِّ قَلْبِي مِنْ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنْ ‏ ‏الدَّنَسِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('27607395-6401-5622-8117-ee26a6a28221', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '62', '‏ ‏أَخْبَرَنِي ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏قَالَ شَهِدْتُ ‏ ‏عَوْفَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى مَيِّتٍ فَسَمِعْتُ مِنْ دُعَائِهِ وَهُوَ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ وَأَكْرِمْ ‏ ‏نُزُلَهُ ‏ ‏وَأَوْسِعْ مُدْخَلَهُ وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ وَنَقِّهِ مِنْ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنْ ‏ ‏الدَّنَسِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e584b0a-6c35-50fb-bbbf-9b630ee972a4', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '63', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3f6bf74e-9a5b-51ba-a222-6d692a5e6c7c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '64', '‏ ‏أَخْبَرَنِي ‏ ‏إِبْرَاهِيمُ بْنُ الْحَسَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زِيَادُ بْنُ سَعْدٍ ‏ ‏أَنَّ ‏ ‏ثَابِتًا ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏ ‏أَخْبَرَنِي ‏ ‏إِبْرَاهِيمُ بْنُ الْحَسَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زِيَادُ بْنُ سَعْدٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏هِلَالُ بْنُ أَسَامَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُخْبِرُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7145761a-7892-5648-a647-40590b7e6c10', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '65', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏وَأَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيُرِقْهُ ثُمَّ لِيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏لَا أَعْلَمُ أَحَدًا تَابَعَ ‏ ‏عَلِيَّ بْنَ مُسْهِرٍ ‏ ‏عَلَى قَوْلِهِ فَلْيُرِقْهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a1af2bab-9e66-508f-a71d-d8219037bbaa', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '66', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى الصَّنْعَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْمُغَفَّلِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ الْكِلَابِ وَرَخَّصَ فِي كَلْبِ الصَّيْدِ وَالْغَنَمِ وَقَالَ إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلُوهُ سَبْعَ مَرَّاتٍ ‏ ‏وَعَفِّرُوهُ ‏ ‏الثَّامِنَةَ بِالتُّرَابِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('99f6af5c-a347-5ce9-942b-5003e172e87b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '67', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدَةَ بِنْتِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏دَخَلَ عَلَيْهَا ثُمَّ ذَكَرَتْ كَلِمَةً مَعْنَاهَا فَسَكَبْتُ لَهُ وَضُوءًا فَجَاءَتْ هِرَّةٌ فَشَرِبَتْ مِنْهُ ‏ ‏فَأَصْغَى ‏ ‏لَهَا الْإِنَاءَ حَتَّى شَرِبَتْ قَالَتْ ‏ ‏كَبْشَةُ ‏ ‏فَرَآنِي أَنْظُرُ إِلَيْهِ فَقَالَ أَتَعْجَبِينَ يَا ابْنَةَ أَخِي فَقُلْتُ نَعَمْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّمَا هِيَ مِنْ ‏ ‏الطَّوَّافِينَ ‏ ‏عَلَيْكُمْ وَالطَّوَّافَاتِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
